(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-evocut-multilayer"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-1\">一 · 事故现场：首层打分剪掉的 token，在第 17 层成了答案</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-2\">二 · 机制拆解：演化分数如何在数据流里被累出来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-3\">三 · 系统代价：统计缓冲挤占的是 KV cache 的同一块显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-4\">四 · 一次性剪枝的同步陷阱与选层调参</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-5\">五 · 剪枝点选错层时，省下的算力会以精度和显存的形式还回去</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-6\">六 · 拼接入口与统计缓存的建立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-7\">七 · 逐层注意力质量的记录</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-8\">八 · 演化分数的累积与层权重</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-9\">九 · 预设层的一次性剪枝与 KV 重排</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-10\">十 · 后续层仅对保留 token 计算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-11\">十一 · 步骤间的耦合与失败面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-12\">十二 · 剪枝层深度与统计缓存预算的耦合边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-13\">十三 · 演化分数的逐项含义与可计算形式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-14\">十四 · 推导的关键一步：为什么累积优于单层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-15\">十五 · 伪代码：从记录到一次性剪枝</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-16\">十六 · 选层与压缩率的联合调参</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-17\">十七 · 数值稳定性与统计口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-18\">十八 · 剪枝层深度与统计缓存：EvoCut 的边界条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-19\">十九 · 请求形态：什么输入才让演化分数有意义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-20\">二十 · 并发与批大小：被统计缓存反向约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-21\">二十一 · SLO 关注点：TTFT 是主战场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-22\">二十二 · 负载不对时的三种失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-23\">二十三 · 配方落地：分桶与回退</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-24\">二十四 · 负载错配时，EvoCut 的收益会先于精度一起蒸发</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-25\">二十五 · 硬件档位：按统计缓存而非算力选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-26\">二十六 · 并行拓扑：沿用原 LLM 切分，剪枝层是同步点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-27\">二十七 · 量化方案：统计路径与计算路径分开对待</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-28\">二十八 · KV 策略：一次性重排与索引一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-29\">二十九 · 调度参数：批大小、剪枝层与压缩率的三角约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-30\">三十 · 可复现配置的落地检查项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-31\">三十一 · 剪枝层深度与统计缓存的预算折中：EvoCut 配方的边界条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-32\">三十二 · 多层统计缓存的显存账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-33\">三十三 · 带宽：统计写入与 KV 重排的双重压力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-34\">三十四 · 通信：并行拓扑下的统计聚合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-35\">三十五 · 功耗与热：观测窗口的持续占用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-36\">三十六 · 尾延迟：剪枝点作为全局同步点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-37\">三十七 · 规模上去以后哪里先崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-38\">三十八 · 统计缓存的显存墙与带宽账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-39\">三十九 · 剪枝层深度是吞吐与精度的单旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-40\">四十 · 一次性重排的同步陷阱与尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-41\">四十一 · 精度回退的定位：剪枝层选错与统计口径错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-42\">四十二 · OOM 的真实来源：统计缓存与 KV cache 争抢同一块显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-43\">四十三 · 批抖动：批大小被统计缓存钉死后的调度退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-44\">四十四 · 路由不均与尾延迟尖刺：剪枝层成为同步屏障</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-45\">四十五 · 解码一致性：KV 重排与后续层不同步的隐性错误</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-46\">四十六 · 监控面板与回滚阶梯的落地形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-47\">四十七 · 同族谱系：四类判据的分水岭</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-48\">四十八 · 决策表：按约束选算法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-49\">四十九 · 适用条件的量化判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-50\">五十 · 与合并类、熵类的接口差异</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-51\">五十一 · 组合与降级路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-52\">五十二 · 选型的工程落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-evocut-multilayer-sec-53\">五十三 · 与同族剪枝方案的分界：选型判据与失效边界</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">视觉 token 与文本拼接进入 LLM</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">逐层记录视觉 token 的注意力质量</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">累积多层显著性得到演化分数</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">在预设层按演化分数执行一次性剪枝并重排 KV</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">后续层仅对保留 token 计算</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-evocut-multilayer-sec-1\">一 · 事故现场：首层打分剪掉的 token，在第 17 层成了答案</h3>\n<p>一个已经上线的图文问答服务出现了难以复现的精度塌陷：同一批高分辨率商品图，用户问“包装右下角的净含量是多少”，模型在压缩率 70% 的配置下给出的数字与未压缩路径不一致，而未压缩路径是对的。排查发现，出错的样本有一个共同特征——答案所需的视觉证据位于图像边缘的小字区域，这些 token 在 LLM 第 1 层的注意力质量极低，被按首层分数排序的 top-k 剪枝直接剔除。但在未剪枝的路径里，这些 token 的注意力质量随层数推进持续上升，到中后层才成为文本查询真正聚焦的对象。首层打分器看到的是“此刻不重要”，而模型真正需要的是“稍后会重要”。这就是仅按单层或固定层打分剪枝的结构性缺陷：它把显著性当成静态属性，而显著性在 LLM 的层间是动态演化的。</p>\n<p>这类事故的代价不是一次错误的回答，而是整条服务链的信任折损。工程上它表现为三个难以归因的症状：其一，精度损失与压缩率不成线性关系，某些压缩档位反而比更高压缩率更差，因为被误删的恰是“慢热型”token；其二，离线评测集上看不出问题，因为评测样本的答案区域大多居中且显著，线上长尾输入才触发；其三，调参无法收敛——把剪枝层从第 1 层挪到第 4 层，一部分样本恢复、另一部分恶化，因为不同样本的显著性峰值层不同。运维侧只能靠下调压缩率换取精度，直接抬高 TTFT 与显存占用，把容量规划打回原点。</p>\n<p>EvoCut 针对的正是这个具体问题：视觉 token 在 LLM 不同层的显著性会动态演化，仅按首层或固定层打分剪枝会误删后续层才变重要的 token，导致相同压缩率下精度受损。它不解决“视觉编码器本身太慢”“文本侧 KV 太长”“量化误差”这些问题，也不改变模型权重与并行拓扑；它只回答一件事——在给定压缩预算下，保留集合应当由跨层演化轨迹决定，而不是由某一层的瞬时分数决定。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-2\">二 · 机制拆解：演化分数如何在数据流里被累出来</h3>\n<p>EvoCut 的数据流顺序是固定的：视觉 token 与文本拼接进入 LLM；逐层记录视觉 token 的注意力质量；累积多层显著性得到演化分数；在预设层按演化分数执行一次性剪枝并重排 KV；后续层仅对保留 token 计算。关键在于“记录”与“剪枝”在时间上的分离——剪枝不是每层都做，而是等到显著性轨迹已经足够可辨的那一层才动手，此前所有层都保留完整 token 集，只做统计。</p>\n<p>演化分数的形式化表达为跨层加权累积。给定剪枝层深度 $L_p$、第 $l$ 层视觉 token $i$ 的注意力质量 $a_i^{(l)}$ 与层权重 $w_l$，有</p>\n<div class=\"formula\">$$s_i=\\sum_{l=1}^{L_p} w_l \\cdot a_i^{(l)},\\quad \\text{keep}=\\text{top-}B\\left(\\{s_i\\}\\right)$$</div>\n<p>其中 $B$ 为保留预算。$w_l$ 的作用是调节早期层与临近剪枝层的话语权：若 $w_l$ 随层数递增，则临近剪枝层的证据占主导，早期层的低分不会一票否决；若取均匀权重，则等价于对轨迹做算术平均。另一组等价写法用衰减因子 $\\gamma$ 表达同一思想：</p>\n<div class=\"formula\">$$s_i=\\sum_{l=l_0}^{l_1}\\gamma^{\\,l-l_0}\\,a_i^{(l)}$$</div>\n<p>工程实现上，逐层记录注意力质量不需要额外的前向计算，只需在注意力 kernel 输出侧挂一个归约：对每个视觉 token 位置，把该层所有查询头、所有文本查询对它的注意力权重求和或求均值，得到一个标量 $a_i^{(l)}$，写入一块按 (层, token) 索引的统计缓冲。这块缓冲是 EvoCut 全部额外开销的来源，也是它区别于单层打分方案的本质代价。</p>\n<p>剪枝动作集中在一层完成，带来一个容易被低估的收益：KV 重排只需一次。保留集合确定后，把视觉 token 对应的 K/V 行按新索引压缩重排，后续层的注意力计算规模直接按 $B$ 而非原始 token 数展开。若改成逐层渐进剪枝，每层都要重排一次 KV 并处理位置索引映射，重排开销与同步次数随层数线性增长；EvoCut 把这份代价压成常数次，代价是剪枝前所有层都必须按全量 token 计算。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-3\">三 · 系统代价：统计缓冲挤占的是 KV cache 的同一块显存</h3>\n<p>EvoCut 的显存账要和 KV cache 放在同一张预算表上算。多层注意力统计缓冲的规模随“层数 × 视觉 token 数 × 每 token 统计量”增长，而视觉 token 数在高分辨率图像与长视频输入下本身就很大。这意味着在长视频或高分辨率输入下，统计缓冲可能挤占 KV cache 预算，迫使批大小下调——这是该算法最直接的失败模式，也是容量规划时必须前置扣除的一项。定性地说：层数越多、token 越多，缓存越大，批大小与剪枝层深度之间构成一组必须折中的三角约束。</p>\n<p>带宽侧的压力来自统计的写入与回读。每层都要把 $a_i^{(l)}$ 写回缓冲，剪枝层再整体读出做排序，这两段流量与视觉 token 数成正比，且发生在预填阶段——恰好是 TTFT 最敏感的区间。因此 EvoCut 的 SLO 关注点集中在 TTFT：剪枝点集中在一层、KV 重排代价可控，预填后段算力随保留 token 数下降，但剪枝之前的层仍按全量计算，TTFT 的收益只体现在剪枝层之后的部分。若把剪枝层放得很深，收益窗口被压缩；放得很浅，统计样本不足、误删风险上升。</p>\n<p>算力账同样要分段看。设总层数 $L$、剪枝层 $L_p$、原始视觉 token 数 $N$、保留数 $B$，视觉侧注意力计算量近似正比于 $L_p \\cdot N + (L-L_p)\\cdot B$。相对全量基线 $L\\cdot N$，节省比例取决于 $L_p/L$ 与 $B/N$ 的乘积关系：浅层剪枝（$L_p$ 小）能把大部分层切换到 $B$ 的规模，收益最大；深层剪枝则大部分算力仍花在全量 token 上。这正是“浅层剪枝收益大但风险高”的算术根源——收益与误删风险由同一个参数 $L_p$ 同时驱动，无法解耦。</p>\n<table class=\"mini\"><thead><tr><th>代价项</th><th>随什么增长</th><th>落在哪个 SLO 上</th><th>工程对策</th></tr></thead><tbody><tr><td>多层注意力统计缓冲</td><td>层数 × 视觉 token 数</td><td>显存预算 → 批大小</td><td>与 KV cache 同表核算，前置扣除</td></tr><tr><td>统计写入与回读带宽</td><td>视觉 token 数 × 层数</td><td>TTFT</td><td>归约在注意力输出侧就地完成</td></tr><tr><td>剪枝前全量计算</td><td>剪枝层深度 $L_p$</td><td>TTFT、算力</td><td>按模型深度调 $L_p$</td></tr><tr><td>KV 重排</td><td>保留集合大小（一次）</td><td>预填尾段延迟</td><td>集中一层执行，避免逐层重排</td></tr></tbody></table>\n<p>一个具体的工程场景：长视频输入使视觉 token 数达到使统计缓冲与 KV cache 争夺同一块 HBM 的程度，服务被迫把批大小从原配置下调，吞吐随之下降。此时若为了保住吞吐而把剪枝层提前，误删风险上升，精度回退又迫使压缩率下调，形成负反馈。EvoCut 的适用边界由此显形：它适合层数较深、显著性跨层演化明显的 VLM，且部署方能够接受多层注意力统计的显存开销；当输入形态使 token 数远超统计缓冲的可承受范围时，它不是首选。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-4\">四 · 一次性剪枝的同步陷阱与选层调参</h3>\n<p>第三个失败模式不在精度侧，而在正确性侧：一次性剪枝后 KV 重排若与后续层注意力计算不同步，保留 token 的位置索引会错乱，影响解码一致性。机制上，剪枝改变了视觉 token 在序列中的排布，后续层的注意力掩码、位置编码、KV 读取偏移都必须基于重排后的索引；若重排写入与下一层读取之间缺少同步点，或在连续批处理中不同请求的重排交错执行而未做隔离，就会出现“保留集合正确但索引错位”的静默错误——输出看似流畅，实则引用了错误的视觉证据。这类错误比精度回退更难发现，因为它不表现为明显的答非所问，而是细微的事实漂移。</p>\n<p>选层调参是另一处必须写进部署配方的工程判断。剪枝层位置需按模型深度调参，没有跨模型通用的默认值：浅层剪枝收益大但误删风险高，选层不当会在相同压缩率下出现精度回退。可行的调参路径是把 $L_p$ 当作与压缩率并列的二维搜索维度，在代表性长尾样本上同时评估 TTFT 与答案一致性，而不是只在小规模显著样本上验证。层权重 $w_l$ 与 $L_p$ 存在耦合：$L_p$ 越浅，越需要给临近层更高权重以压制早期噪声；$L_p$ 越深，均匀权重即可。</p>\n<p>与相邻算法的边界也在这里划清。ApET 以合并前后注意力近似误差为准则做贪心合并，ERA 用熵与 sink 修正联合打分，VPRune 在 LLM 之前用视觉侧打分；EvoCut 的独特之处是跟踪跨层演化轨迹并在预设层一次性剪枝。这意味着当视觉编码器侧已有可靠显著性、且 LLM 层间演化不明显时，前置剪枝方案更省显存；当显著性确实跨层漂移时，EvoCut 的统计开销才换得回精度。判断依据不是压缩率高低，而是“显著性峰值层是否分散”——峰值越分散，单层打分越不可靠，跨层累积的边际收益越大。</p>\n<p>把适用边界收束成一句可执行的判断：若部署预算无法为多层统计缓冲单独划出一块显存、且输入 token 数已逼近 KV cache 的容量红线，EvoCut 的统计开销会直接转化为批大小损失，此时应退回单层打分并接受精度折损，或改用前置视觉侧剪枝；反之，若模型层数深、显著性轨迹分散、TTFT 是主 SLO 且显存尚有余量，EvoCut 用一次 KV 重排换来的后段算力下降是划算的。剪枝层深度 $L_p$ 必须与压缩率一同进入容量规划表，而不是留作上线后的调参余量。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-5\">五 · 剪枝点选错层时，省下的算力会以精度和显存的形式还回去</h3>\n<p>一个典型线上事故形态是这样的：视觉编码器给出数千个 token，服务端按首层注意力分数直接砍到固定预算，预填阶段算力确实下降，TTFT 看起来达标；但解码到中后段开始出现答非所问——被删掉的 token 恰恰是在第 20 层之后才被文本查询“激活”的那批。更麻烦的是这类回退不可在线观测：单层打分方案没有任何跨层统计可供回溯，运维只能看到端到端质量指标漂移，却定位不到是哪一层剪错了。EvoCut 的边界正在这里：它解决的是“显著性随层深动态演化、单层或固定层打分必然误删”这一类问题，用跨层累积分数替代单层分数，$$s_i=\\sum_{l=l_0}^{l_1}\\gamma^{l-l_0}\\,a_i^{(l)},\\quad \\text{keep}=\\text{top-}k\\left(\\{s_i\\}\\right)$$ 把决策推迟到预设剪枝层一次性执行。它不解决的是：视觉侧本身就没编码出有效信息的请求（此时任何打分都无从区分）、以及必须在极浅层就完成压缩以抢首 token 的场景——那类需求属于 VPRune 一类在 LLM 之前做视觉侧打分的位置。</p>\n<p>代价必须提前算清。逐层记录视觉 token 注意力质量意味着在剪枝层之前要保留一份跨层统计缓存，其规模随层数、token 数线性增长，与 KV cache 争夺同一块 HBM。长视频或高分辨率输入下，这份统计缓存会直接把可承载批大小压下来：吞吐的损失往往吃掉剪枝带来的算力收益。因此适用边界可以写成一条工程判据——只有当“统计缓存占用 ÷ 剪枝后节省的 KV 与算力”在目标 SLO 下为正，方案才成立。层数越深、演化越明显的 VLM 越划算；浅层模型或 token 数本就很少的请求，缓存开销占比过高，不如退回单层方案。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统表现</th><th>工程对策</th></tr></thead><tbody><tr><td>剪枝层选得过浅</td><td>相同压缩率下精度回退，误删后续才重要的 token</td><td>按模型深度调参，用离线校准确定剪枝层</td></tr><tr><td>长视频/高分辨率输入</td><td>多层统计缓存挤占 KV cache，批大小被迫下调</td><td>限制统计缓存预算，或对超长请求降级为单层打分</td></tr><tr><td>KV 重排与后续层计算不同步</td><td>保留 token 位置索引错乱，解码一致性受损</td><td>把重排绑定在剪枝层同一次前向内完成</td></tr></tbody></table>\n<p>最后一条最容易被低估：一次性剪枝把 KV 重排集中在一层，代价可控是优点，但前提是重排与后续层的注意力计算严格同步——位置索引一旦错位，后续所有层的注意力都建立在错误的 token 序上，输出会呈现“局部通顺、整体漂移”的形态，比直接崩溃更难排查。这也是 EvoCut 与 ApET 的贪心合并、ERA 的熵与 sink 联合打分在工程形态上的分野：后两者把准则摊在打分环节，EvoCut 把风险集中在一个可校准的剪枝点上，收益与风险都收敛到“选层”这一个旋钮上。</p>\n<h3 id=\"alg-evocut-multilayer-sec-6\">六 · 拼接入口与统计缓存的建立</h3>\n<p>EvoCut 的第一步发生在视觉编码器输出与文本嵌入拼接之后、LLM 首层注意力之前。此时系统拿到的是完整的视觉 token 序列 $V=\\{v_i\\}_{i=1}^{N}$ 与文本 token 序列拼接而成的混合序列，序列长度为 $N+M$。这一步的输入是视觉 token 的隐状态与位置编码，输出是一个被标记为“待观测”的 token 子集索引表——EvoCut 需要在这张表上逐层挂载注意力统计钩子，而不是在首层就做打分决策。</p>\n<p>代价集中在缓存分配上。单层打分方案只需在某一层保留一份 $N$ 维的注意力向量；EvoCut 要跨 $L_p$ 层累积，缓存形状是 $L_p \\times N$ 的注意力质量矩阵，若以 FP16 存储，其字节数为 $2 \\cdot L_p \\cdot N$。当 $N$ 达到数千量级、$L_p$ 取模型深度的三分之一到二分之一时，这份统计缓存会与 KV cache 争夺同一块 HBM。工程上的直接后果是批大小被压缩：调度器必须在显存预算里先划出统计缓存的空间，剩下的才给 KV cache，于是连续批处理的并发请求数下降，吞吐随之走低。一个具体例子是长视频输入：一段多帧视频展开后视觉 token 数量远超单图，统计缓存按 $L_p \\times N$ 线性膨胀，此时若不设缓存上限，KV cache 预算会被挤占，解码阶段的 batch 被迫下调。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-7\">七 · 逐层注意力质量的记录</h3>\n<p>进入第 $l$ 层后，EvoCut 在该层注意力计算完成时截取视觉 token 位置上的注意力质量 $a_i^{(l)}$。这里的“注意力质量”不是单个 head 的单次 softmax 值，而是对该层所有 query 位置、所有 head 做归约后的标量：对视觉 token $i$，把它作为 key 被文本 query 与视觉 query 关注的权重求和，得到该层对 token $i$ 的总关注度。归约后的结果是每层一个长度为 $N$ 的向量，写入第一步分配的统计缓存第 $l$ 行。</p>\n<p>这一步的输入是该层的 attention score 矩阵，输出是 $a_i^{(l)}$ 向量。代价是带宽：每层都要把 attention score 从片上寄存器或 shared memory 读出并做归约，归约本身是轻量算子，但读出的数据量与该层 query 数乘以视觉 token 数成正比。在 Blackwell 的 tcgen05 MMA 路径上，attention 的中间结果本就落在 TMEM 中，归约需要一次 TMEM 到寄存器的搬运，再写回 HBM 的统计缓存。这条搬运链路与主计算流共享带宽，因此在预填阶段的高算力密度下，统计写入会成为可见的额外延迟项。伪代码思路如下：</p>\n<div class=\"formula\">$$\\text{for } l \\in [1, L_p]:\\quad a^{(l)} \\leftarrow \\text{reduce}\\big(\\text{attn}^{(l)}[:,\\,V]\\big);\\quad \\text{cache}[l] \\leftarrow a^{(l)}$$</div>\n<p>注意归约的维度选择直接影响统计的稳定性：若只对文本 query 归约，视觉 token 之间的相互关注被丢弃，后续层才变重要的 token 可能因为缺少视觉侧证据而得分偏低；若对全部 query 归约，统计更完整但归约代价更高。这个取舍在长序列预填时尤为明显。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-8\">八 · 演化分数的累积与层权重</h3>\n<p>累积发生在剪枝层 $L_p$ 到达之前。EvoCut 把各层注意力质量按层权重 $w_l$ 加权求和，得到每个视觉 token 的演化分数：</p>\n<div class=\"formula\">$$s_i=\\sum_{l=1}^{L_p} w_l \\cdot a_i^{(l)}$$</div>\n<p>输入是统计缓存中的 $L_p$ 行向量，输出是长度为 $N$ 的演化分数向量。层权重 $w_l$ 的设计意图是让靠近剪枝层的层贡献更大——深层注意力更接近最终语义决策，浅层注意力则更多反映局部纹理与位置。这与前文给出的指数衰减形式 $\\gamma^{l-l_0}$ 是同一族思路：越靠近剪枝点，权重越高。工程上 $w_l$ 可以是预设的几何衰减序列，也可以按模型深度归一化，但无论哪种，它都是需要在部署前标定的超参数，而不是运行时自适应量。</p>\n<p>代价是显存驻留时间：统计缓存必须从第 1 层一直保留到第 $L_p$ 层，期间不能被复用或释放。这意味着在预填的整个前段，HBM 中始终有一块 $L_p \\times N$ 的活跃区域。若把剪枝层设得深，缓存驻留时间变长，与 KV cache 的峰值占用重叠更多；若设得浅，缓存小但误删风险上升。累积本身是 $O(L_p \\cdot N)$ 的逐元素乘加，算力代价可忽略，真正的代价是这块显存的时间积分——它决定了同一张卡上能同时跑多少条请求。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-9\">九 · 预设层的一次性剪枝与 KV 重排</h3>\n<p>到达第 $L_p$ 层时，EvoCut 执行唯一一次剪枝决策：对 $\\{s_i\\}$ 排序取前 $B$ 个 token 构成保留集合，其余视觉 token 被丢弃。输入是演化分数向量与当前 KV cache 中的视觉 token 条目，输出是重排后的 KV cache 与一份位置索引映射表。保留率 $r=B/N$ 是压缩率的直接控制量，$B$ 由显存预算与精度容忍度共同决定。</p>\n<p>KV 重排是这一步的主要工程动作。视觉 token 的 KV 条目在 cache 中原本按原始位置连续存放，剪枝后需要把保留条目紧凑排列，并同步更新后续层注意力计算所用的位置索引。由于剪枝点集中在一层，重排只需执行一次，代价是一次 $O(B \\cdot d)$ 的 KV 拷贝（$d$ 为 head 维度乘层数对应的条目宽度），而不是每层都做。这正是 EvoCut 相对逐层压缩方案的结构性优势：重排的带宽开销被摊薄到单点。但重排必须与后续层的注意力计算严格同步——若索引映射表更新滞后于下一层的 KV 读取，保留 token 的位置索引会错乱，解码一致性被破坏。工程上这要求重排与下一层的 launch 之间插入显式的同步点，或在 kernel 内用同一份索引表完成寻址。</p>\n<p>剪枝后的直接收益体现在预填后段：第 $L_p+1$ 层起，注意力计算的 key/value 长度从 $N+M$ 降到 $B+M$，每层的注意力算力与 KV 读取带宽按 $B/N$ 比例下降。对 TTFT 而言，这部分节省是确定的，因为剪枝点位置固定、节省量可预估；这也是 EvoCut 把 SLO 关注点放在 TTFT 上的原因——预填后段的算力曲线在剪枝点处出现一个可计算的台阶。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-10\">十 · 后续层仅对保留 token 计算</h3>\n<p>剪枝层之后的每一层，输入是重排后的 KV cache 与索引映射表，输出是该层的隐状态，且计算图里不再包含被丢弃的视觉 token。这一步没有额外的统计开销，也没有再次打分的逻辑——EvoCut 的设计是把所有决策压缩到一个点上，后续层纯粹享受压缩带来的算力与带宽节省。</p>\n<p>代价特征在这里发生转换：前四步的代价是显存与带宽的“前置投入”，本步的代价是索引寻址的间接性。由于 KV cache 经过重排，保留 token 在 cache 中的物理位置不再等于其逻辑位置，注意力 kernel 需要用映射表做一次间接寻址。若映射表放在 HBM，每次 KV 读取多一次索引加载；若放在 shared memory 或常量内存，间接寻址的额外延迟可被隐藏。在 Blackwell 的 2-SM MMA 协作模式下，两个 SM 共享同一份 KV 分片，映射表需要在协作对之间保持一致，这要求重排后的索引布局按 SM 对对齐，否则跨 SM 的 KV 读取会出现分片边界错位。</p>\n<p>一个具体例子可以说明这条链路的整体代价结构：假设某 VLM 有数十层、视觉 token 数百个、剪枝层设在模型中部、保留率取一个中等比例。前段每层写入统计缓存带来的带宽增量，与后段每层因 KV 缩短而节省的带宽相比，前者是常数级的小量、后者是随层数累积的大量；因此净收益随模型深度增加而放大。但若剪枝层设得过浅，前段统计窗口太短，演化分数不足以区分“后续才重要”的 token，相同压缩率下精度回退；若设得过深，统计缓存驻留过久，批大小被压低，吞吐收益被显存代价抵消。选层因此不是精度单目标问题，而是精度、显存驻留与批大小三者的联合调参。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-11\">十一 · 步骤间的耦合与失败面</h3>\n<p>把五步串起来看，EvoCut 的数据流有两个耦合点值得工程上特别对待。第一个耦合点是统计缓存的形状与剪枝层深度：$L_p$ 同时决定了缓存大小、驻留时长和演化分数的证据量，三者方向并不一致——增大 $L_p$ 提升分数质量却恶化显存占用，这是一条需要按模型深度实测的折中曲线。第二个耦合点是重排与后续层计算的同步：一次性剪枝把重排代价压到单点，但也把正确性风险集中到单点，索引映射表的任何滞后都会污染此后所有层的解码。</p>\n<p>失败模式因此可以归为三类。其一是显存挤占：多层统计缓存在长视频或高分辨率输入下膨胀，挤占 KV cache 预算，迫使批大小下调，吞吐不升反降。其二是选层不当：浅层剪枝收益大但误删风险高，在相同压缩率下出现精度回退，且这种回退在单层打分方案上不会出现，容易被误判为模型问题而非配置问题。其三是重排不同步：剪枝后 KV 重排若与后续层注意力计算不同步，保留 token 的位置索引错乱，表现为解码输出漂移而非崩溃，排查成本高。工程判断上，这三类失败都指向同一个约束——EvoCut 的收益来自“决策集中”，其代价也来自“决策集中”，部署时必须把剪枝层深度、统计缓存上限与重排同步点作为一组联动参数来标定，而不是各自独立调优。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-12\">十二 · 剪枝层深度与统计缓存预算的耦合边界</h3>\n<p>EvoCut 的失效点不在打分公式本身，而在两个可调量互相咬合：剪枝层深度 $L_p$ 与多层注意力统计的缓存预算。逐层记录 $a_i^{(l)}$ 意味着在 $L_p$ 层之前，视觉 token 的注意力质量必须持续驻留；缓存规模随视觉 token 数 $N_v$ 与 $L_p$ 线性增长，即 $O(N_v\\cdot L_p)$。当输入是长视频或高分辨率图像、$N_v$ 抬升一个量级时，这份统计缓存会直接挤占 KV cache 预算，连续批处理的批大小被迫下调，吞吐随批大小近似线性回落，而 TTFT 因预填阶段仍需遍历全部视觉 token 而得不到同等比例的改善。这就是该方案的系统代价：它用显存与带宽换精度，且这笔开销发生在预填最紧张的阶段。</p>\n<p>选层是第二个边界。浅层剪枝让后续所有层的算力与 KV 读写都按保留 token 数缩减，收益最大；但浅层注意力尚未分化，显著性排序噪声大，误删的 token 在后续层才变得重要，相同压缩率下精度回退。深层剪枝统计更可靠，可节省的后续层算力却已所剩无几。工程判断是把 $L_p$ 当作按模型深度标定的超参，用少量校准样本扫描若干候选层，观察保留集合与全量注意力 top-k 的重合度，而非凭经验取中段。层权重 $w_l$ 同样需要标定，若各层等权，早期噪声层会污染累积分数。</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>表现</th><th>系统代价落点</th></tr></thead><tbody><tr><td>$N_v$ 大、$L_p$ 深</td><td>统计缓存膨胀</td><td>显存、批大小、吞吐</td></tr><tr><td>$L_p$ 过浅</td><td>排序噪声大、误删</td><td>精度回退</td></tr><tr><td>重排与后续层不同步</td><td>位置索引错乱</td><td>解码一致性</td></tr></tbody></table>\n<p>第三个失效条件是时序耦合：一次性剪枝后 KV 重排必须与后续层的注意力计算严格同步，保留 token 的位置索引、位置编码与因果掩码需在同一事务内更新。若重排异步于下一层的读取，索引错乱不会报错，只会让解码输出漂移，这类问题在长上下文下难以定位。因此 EvoCut 适合层数较深、显著性跨层演化明显且能接受统计缓存开销的 VLM；对显存紧、批大小敏感的在线服务，应优先压缩 $L_p$ 或改用单层打分方案，把省下的预算留给 KV cache。</p>\n<h3 id=\"alg-evocut-multilayer-sec-13\">十三 · 演化分数的逐项含义与可计算形式</h3>\n<p>EvoCut 的核心打分式在正文中已给出两种等价写法，本部分只做逐项拆解与工程化。给定视觉 token 集合 $\\{i\\}$，第 $l$ 层记录的注意力质量为 $a_i^{(l)}$，剪枝层深度为 $L_p$，则演化分数为</p>\n<div class=\"formula\">$$s_i=\\sum_{l=l_0}^{l_1}\\gamma^{\\,l-l_0}\\,a_i^{(l)},\\qquad \\text{keep}=\\text{top-}k\\big(\\{s_i\\}\\big)$$</div>\n<p>四项各有明确职责。求和区间 $[l_0,l_1]$ 是观测窗口，决定“演化”被观察的跨度；$l_0$ 取视觉 token 与文本完成拼接后的第一层，$l_1$ 即剪枝层 $L_p$，因此窗口上界与剪枝点是同一个可调参数，而不是两个独立旋钮。$\\gamma$ 是层间衰减因子，$\\gamma&lt;1$ 时越靠近剪枝层的层贡献越大，理由直接：靠近剪枝层的注意力分布更接近后续层真正需要的分布，早期层的分数只是“曾经重要”。$a_i^{(l)}$ 是注意力质量，工程上取该层视觉 token $i$ 收到的注意力权重按头求和或按头取最大值，二者差别在于是否允许“单头专精”的 token 存活——取 max 更宽容，取 sum 更保守。$\\text{top-}k$ 的 $k$ 由压缩率反推，$k=\\lceil \\rho N_v\\rceil$，$N_v$ 为视觉 token 数，$\\rho$ 为保留比例。</p>\n<p>与可用事实中给出的加权写法 $s_i=\\sum_{l=1}^{L_p} w_l\\cdot a_i^{(l)}$ 相比，几何衰减写法把 $L_p$ 个自由权重压缩成一个 $\\gamma$，参数量从 $O(L_p)$ 降到 $O(1)$，代价是失去对特定层的强调能力。工程判断：层数深、演化剧烈的模型用几何衰减足够；若某几层被证实是“显著性翻转层”，再退回显式 $w_l$ 并只调那几个。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-14\">十四 · 推导的关键一步：为什么累积优于单层</h3>\n<p>推导的起点不是公式变形，而是一个反事实假设。设单层打分方案在层 $l_s$ 处按 $a_i^{(l_s)}$ 排序保留前 $k$ 个 token，EvoCut 按 $s_i$ 保留。定义误删事件 $E_i$：token $i$ 在 $l_s$ 层排名落在前 $k$ 之外，但在剪枝层 $L_p$ 的注意力质量排名进入前 $k$。单层方案必然删掉 $i$，EvoCut 只有在 $\\gamma^{L_p-l_s}a_i^{(L_p)}$ 不足以把 $s_i$ 顶进前 $k$ 时才删掉它。</p>\n<p>关键一步是把“是否误删”转成对衰减因子的约束。设 token $i$ 在早期层质量低、在剪枝层质量高，另一 token $j$ 反之，且二者在剪枝层的质量差为 $\\Delta=a_i^{(L_p)}-a_j^{(L_p)}&gt;0$，早期层质量差为 $\\delta=a_j^{(l_s)}-a_i^{(l_s)}&gt;0$。EvoCut 保住 $i$ 的条件是</p>\n<div class=\"formula\">$$\\gamma^{\\,L_p-l_s}\\cdot\\Delta \\;&gt;\\; \\sum_{l=l_0}^{l_s}\\gamma^{\\,l-l_0}\\,\\delta$$</div>\n<p>右侧是早期层对 $j$ 的累积优势，左侧是剪枝层附近对 $i$ 的补偿。这个不等式说明：$\\gamma$ 越小（衰减越快），越倾向于相信靠近剪枝层的信号，误删“后起之秀”的概率越低；$\\gamma$ 越接近 1，累积窗口内所有层等权，早期噪声会淹没后期信号。这就是“跨层累积”相对“单层固定层打分”的实质收益——它不是简单多看了几层，而是通过衰减因子给不同层的信息定了价。同一不等式也解释了失败模式：若 $L_p-l_s$ 很大而 $\\gamma$ 不够小，右侧累积项压过左侧，早期误判无法被纠正。</p>\n<p>系统代价上，这个推导直接对应缓存预算。要计算 $s_i$ 必须保留窗口内每层的 $a_i^{(l)}$，缓存量为 $N_v\\times (l_1-l_0+1)$ 个标量（按头聚合后）。以 $N_v$ 数万、窗口十余层计，这是 MB 级到十 MB 级的常驻占用，与 KV cache 争抢同一块显存；带宽上每层都要写一次统计，属于预填阶段的额外流量。因此 $\\gamma$ 与窗口长度不只是精度参数，也是显存参数：缩短窗口等于直接砍缓存。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-15\">十五 · 伪代码：从记录到一次性剪枝</h3>\n<p>下面的伪代码按数据流顺序落到可实现粒度，重点是三处易错点：统计缓存的写入时机、剪枝与 KV 重排的原子性、后续层只对保留 token 计算。</p>\n<ul>\n<li>预填前向逐层执行，视觉 token 位置集合 $V$ 固定不变，文本位置不参与打分。</li>\n<li>每层注意力计算完成后立即聚合 $a_i^{(l)}$，写入按 token 索引的环形缓冲；不要等整段预填结束再回读，否则中间层激活已释放。</li>\n<li>到达 $L_p$ 时冻结缓冲，一次性算 $s_i$、排序、取 top-$k$，随后在同一同步点完成 KV 重排与位置索引重写。</li>\n<li>重排后把保留 token 的索引映射广播给后续所有层，后续层的 attention 与 MLP 只在这些索引上计算。</li>\n</ul>\n<p>伪代码思路（非可执行语言，仅表结构）：</p>\n<p>for $l$ in $[l_0,\\,L_p]$: 计算 attention；对 $i\\in V$ 聚合 $a_i^{(l)}$ 写入 buffer[$i$][$l$]；若 $l=L_p$：对每个 $i$ 累加 $\\gamma^{l-l_0}a_i^{(l)}$ 得 $s_i$；argsort 取前 $k$ 得 keep 集合；按 keep 重排 KV 的 token 维并重写 position_ids；广播 keep 掩码；break 到后续层循环，仅对 keep 索引计算。</p>\n<p>工程代价集中在两处。其一，重排是一次显存内的 gather，代价与 $N_v$ 和 KV 头数成正比，但因为只做一次，相比逐层压缩方案的多次重排，总搬运量可控——这正是“剪枝点集中在一层”的收益来源。其二，后续层算力随 $k$ 线性下降，预填后段的 attention 与 MLP 都变窄，TTFT 的改善主要来自这一段；而剪枝前的层仍是全量计算，所以压缩率对 TTFT 的边际收益随 $L_p$ 前移而增大。失败模式里提到的“重排与后续层不同步导致位置索引错乱”，在伪代码里对应“广播 keep 掩码”这一步必须与 KV 重排处于同一同步点，任何异步都会让后续层读到旧索引。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-16\">十六 · 选层与压缩率的联合调参</h3>\n<p>$L_p$ 与 $\\rho$ 不是独立参数，二者的可行域由第二节的不等式和缓存预算共同界定。把剪枝层前移（$L_p$ 变小）有三个后果：剪枝后节省的算力区间变长，TTFT 收益变大；观测窗口变短，累积统计的缓存变小；但早期层注意力尚未分化，$a_i^{(l)}$ 的判别力弱，误删风险上升。反之 $L_p$ 后移则精度更稳、收益更小、缓存更大。</p>\n<p>可操作的调参顺序是：先固定 $\\rho$，在若干候选 $L_p$ 上比较保留集合与“全量 token 在最终层的注意力排名”的重合度，重合度高说明该层打分已接近最终需求；再固定 $L_p$，扫 $\\rho$ 找精度拐点。$\\gamma$ 的选取可复用第二节的不等式：给定观测到的 $\\Delta$ 与 $\\delta$ 量级，解出使补偿项占优的最大 $\\gamma$。这套流程不需要训练，只需一次校准前向。</p>\n<p>系统侧约束同样参与选层。缓存占用为 $N_v\\times(L_p-l_0+1)$，在长视频或高分辨率输入下 $N_v$ 很大，缓存会挤占 KV cache 预算并迫使批大小下调，吞吐反而下降；此时应缩短窗口而非降低 $\\rho$，因为降低 $\\rho$ 会同时削弱精度与后续层算力，而缩短窗口只损失早期层的判别信息。表格给出三者的定性权衡：</p>\n<table class=\"mini\"><thead><tr><th>调节方向</th><th>精度</th><th>TTFT 收益</th><th>统计缓存</th><th>主要风险</th></tr></thead><tbody><tr><td>$L_p$ 前移</td><td>下降</td><td>增大</td><td>减小</td><td>早期误删</td></tr><tr><td>$L_p$ 后移</td><td>上升</td><td>减小</td><td>增大</td><td>挤占 KV 预算</td></tr><tr><td>$\\rho$ 降低</td><td>下降</td><td>增大</td><td>不变</td><td>相同压缩率下精度回退</td></tr><tr><td>$\\gamma$ 减小</td><td>偏向后期信号</td><td>不变</td><td>不变</td><td>早期信息被丢弃</td></tr></tbody></table>\n<p>一个具体例子：某 VLM 层数较深、视觉 token 在中间层出现明显显著性翻转，若在首层按 $a_i^{(l_0)}$ 剪枝，翻转后才重要的 token 被整批删除，相同 $\\rho$ 下精度受损；把 $L_p$ 移到翻转层之后、$\\gamma$ 取偏小值，累积分数由后期层主导，这些 token 得以保留，而缓存窗口只覆盖翻转层附近若干层，显存增量有限。这就是 EvoCut 相对 VPRune（LLM 之前视觉侧打分）与 ApET（合并前后注意力近似误差贪心合并）的分工位置：它把决策点放在 LLM 内部、且只放一次。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-17\">十七 · 数值稳定性与统计口径</h3>\n<p>公式落地时有两个数值细节决定成败。第一，$a_i^{(l)}$ 的量纲随层变化，深层注意力更集中、熵更低，直接跨层相加会让深层数值天然占优，与 $\\gamma$ 的作用重叠。工程做法是每层先做行内归一化再累加，使 $a_i^{(l)}$ 成为该层视觉 token 上的相对份额，此时 $\\gamma$ 才真正只承担“时间折扣”的角色。第二，softmax 的行最大值偏移会让极小的注意力被压成 0，若某 token 在窗口内所有层都接近 0，其 $s_i$ 恒为 0，排序时与真正无关 token 无法区分——这类 token 应直接归入删除集合，避免 top-$k$ 在零值上做无意义比较。</p>\n<p>统计口径还需与并行拓扑对齐。张量并行下每层注意力按头切分在不同设备上，$a_i^{(l)}$ 的聚合需要一次跨设备归约，若在每层都做归约，通信次数等于窗口长度；更省的做法是各设备本地累积 $s_i$ 的部分和，只在 $L_p$ 做一次全局归约后排序。这把通信从 $O(L_p)$ 次降到 1 次，代价是每台设备都要持有本地缓存，缓存总量随并行度线性增长——这是并行度与显存预算之间的直接交换，也是“规模上限受缓存统计量约束”的具体含义。解码一致性方面，重排后 position_ids 必须按保留顺序重写，否则 RoPE 相位与 KV 位置错配，后续层注意力会读到错误的位置编码，表现为长输出下的重复或截断。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-18\">十八 · 剪枝层深度与统计缓存：EvoCut 的边界条件</h3>\n<p>EvoCut 的收益并非无条件的，其边界由两个量共同决定：剪枝层深度 <span class=\"inline-math\">L_p</span> 与多层注意力统计缓存的占用。演化分数 <span class=\"inline-math\">\\(s_i=\\sum_{l=1}^{L_p} w_l \\cdot a_i^{(l)}\\)</span> 中，<span class=\"inline-math\">L_p</span> 越浅，预填后段可省下的算力越多——因为剪枝后仅对保留 token 计算，后续层的 QK^T 与 FFN 规模随保留数线性下降；但浅层注意力尚未充分分化，<span class=\"inline-math\">a_i^{(l)}</span> 的跨层演化信号弱，按 <span class=\"inline-math\">s_i</span> 排序取前 <span class=\"inline-math\">B</span> 个极易误删那些在深层才被文本查询激活的视觉 token，相同压缩率下精度回退。反之，<span class=\"inline-math\">L_p</span> 越深，统计越可靠，但可剪的层数变少，TTFT 收益被压缩。工程判断是：把 <span class=\"inline-math\">L_p</span> 设在注意力分布开始收敛的层，用少量校准样本扫一遍 <span class=\"inline-math\">L_p</span> 与保留率 <span class=\"inline-math\">B/N</span> 的二维网格，而不是按固定比例拍板。</p>\n<p>第二个边界是统计缓存的显存与带宽代价。逐层记录 <span class=\"inline-math\">a_i^{(l)}</span> 意味着要为每个视觉 token 保存 <span class=\"inline-math\">L_p</span> 个标量，缓存规模约为 <span class=\"inline-math\">\\(N_v \\times L_p \\times 4\\)</span> 字节（FP32 累加）。在长视频或高分辨率输入下 <span class=\"inline-math\">N_v</span> 很大，这块缓存会直接挤占 KV cache 预算，迫使批大小下调，吞吐反而受损。更隐蔽的是写带宽：每层都要把注意力质量写回全局缓冲，若与 KV 写入争抢 HBM 带宽，预填阶段的带宽压力上升。可行的缓解是把 <span class=\"inline-math\">a_i^{(l)}</span> 以 FP16/BF16 累积、按 token 分块驻留 SMEM 后再落盘，并把 <span class=\"inline-math\">w_l</span> 设计成随层递增的权重，让深层信号主导排序，从而允许更小的 <span class=\"inline-math\">L_p</span>。</p>\n<p>第三个失效条件是剪枝与 KV 重排的同步性。一次性剪枝后，保留 token 的位置索引必须与后续层的注意力计算、位置编码、以及 KV cache 的物理布局严格一致；若重排发生在异步流上而后续层已开始读取旧索引，解码会出现位置错乱与一致性漂移。实现上应把重排做成剪枝层内的一个屏障：先按 <span class=\"inline-math\">s_i</span> 生成保留掩码，压缩 KV 并写回新偏移，再释放后续层的计算图。下表给出三个调参维度的代价对照。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>调浅</th><th>调深</th><th>主要代价</th></tr></thead><tbody><tr><td>剪枝层 <span class=\"inline-math\">L_p</span></td><td>省算力多，误删风险高</td><td>统计可靠，TTFT 收益小</td><td>精度回退 vs 延迟</td></tr><tr><td>保留率 <span class=\"inline-math\">B/N</span></td><td>压缩率高，信息损失大</td><td>精度稳，后段算力降幅小</td><td>显存 vs 吞吐</td></tr><tr><td>统计缓存精度</td><td>FP16 省显存，累积误差</td><td>FP32 稳，带宽占用高</td><td>HBM 带宽 vs 排序稳定性</td></tr></tbody></table>\n<p>适用边界因此可写成一句工程判据：EvoCut 适合层数较深、显著性跨层演化明显的 VLM，且多层统计缓存占 KV 预算的比例可控；当输入 token 规模使 <span class=\"inline-math\">\\(N_v \\times L_p\\)</span> 逼近 KV cache 容量时，应退回单层打分或改用视觉侧打分方案（如 VPRune 的路径），把压缩决策前移到 LLM 之外以规避缓存开销。</p>\n<h3 id=\"alg-evocut-multilayer-sec-19\">十九 · 请求形态：什么输入才让演化分数有意义</h3>\n<p>EvoCut 的收益来自“显著性在层间移动”这一事实，因此它天然偏向那些<strong>视觉证据分散、需要多跳整合</strong>的请求。典型形态是图像或视频加文本的 VLM 请求：图中存在多个候选区域，问题要求模型先定位再推理（计数、比较、空间关系、跨帧事件）。这类请求里，早期层的高注意力 token 往往只是显著物体，真正决定答案的 token 在更深处才被文本 query 拉高，单层打分剪枝会直接把它们删掉。相反，纯 OCR 式读取、单物体分类、图像描述这类“答案由局部高显著区域一次性决定”的请求，跨层演化幅度小，EvoCut 的累积分数与首层分数高度重合，多缓存几层注意力统计只是白付显存。</p>\n<p>长度分布上，EvoCut 的成本随视觉 token 数线性增长：缓存的是每层每个视觉 token 的注意力质量，量级为 $L_p \\times N_v$（$L_p$ 为剪枝层深度，$N_v$ 为视觉 token 数）。高分辨率单图（切片后 token 数上千）与长视频（帧数乘以每帧 token）处在分布的长尾，正是缓存压力最集中的区间。文本侧长度影响较小，因为文本 token 不进入演化打分集合，但文本 query 决定了哪些视觉 token 在后层被拉起——短 query 加长视觉上下文是 EvoCut 最舒服的配比，长 query 会稀释注意力质量、拉平演化曲线，使 top-k 选择接近随机。</p>\n<p>一个具体例子：视频问答中问“第三帧里穿红衣的人后来做了什么”，早期层注意力落在画面主体，中间层被“红衣”这个文本线索牵引到对应人物区域，后层才把该区域与动作谓词绑定。若在首层按分数保留 top-k，红衣人物区域大概率被裁掉；EvoCut 的累积分数在该 token 上单调抬升，剪枝点设在中间偏后即可保住它。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-20\">二十 · 并发与批大小：被统计缓存反向约束</h3>\n<p>常规 VLM 推理的批大小由 KV cache 预算决定，EvoCut 把约束前移了一层：多层注意力统计缓存与 KV cache 争同一块显存。设单请求视觉 token 数为 $N_v$、剪枝层深度为 $L_p$、每 token 每层统计占 $b$ 字节，则每请求额外缓存为 $L_p \\cdot N_v \\cdot b$；批大小为 $B$ 时总开销为 $B \\cdot L_p \\cdot N_v \\cdot b$，与 KV cache 之和必须落在显存预算内。于是有效批大小近似为</p>\n<div class=\"formula\">$$B_{\\max}\\approx\\frac{M_{\\text{free}}-M_{\\text{weight}}}{N_v\\big(L_p b+k_v\\big)}$$</div>\n<p>其中 $k_v$ 是每视觉 token 的 KV 占用。分母里 $L_p b$ 这一项是 EvoCut 独有的，它让 $B_{\\max}$ 随剪枝层深度线性下降。工程含义很直接：把剪枝点往后挪一层，精度更稳，但并发掉一档；把剪枝点提前，缓存变小、批变大，却要承担误删风险。这就是“剪枝层位置需按模型深度调参”在容量侧的体现。</p>\n<p>吞吐侧还有一次反向补偿：剪枝点集中在一层，KV 重排只做一次，后续层仅对保留 token 计算，预填后段算力随保留 token 数下降。因此在<strong>预填占主导</strong>的负载（长视觉输入、短输出）里，EvoCut 的吞吐收益能盖过统计缓存的开销；而在<strong>解码占主导</strong>的负载（短视觉、长文本生成）里，剪枝只省了预填的一次性算力，解码每步仍要读保留 token 的 KV，收益被摊薄，统计缓存却全程占着显存。批调度器应把 EvoCut 请求与解码密集型请求分开排队，避免前者把后者的 KV 预算挤掉。</p>\n<p>具体判断：当 $N_v$ 大到使 $L_p b$ 与 $k_v$ 同量级时，EvoCut 的显存代价翻倍，连续批处理的有效并发明显下滑；此时要么降低 $L_p$（提前剪枝），要么对长视频做帧采样先降 $N_v$，再交给 EvoCut 做层内选择。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-21\">二十一 · SLO 关注点：TTFT 是主战场</h3>\n<p>EvoCut 的延迟结构是“前段贵、后段便宜”。前段要跑满 $L_p$ 层并记录注意力质量，与不剪枝的预填前段同价；剪枝层做一次 top-k 选择与 KV 重排，代价可控但不可忽略；后段只对保留 token 计算，注意力与 FFN 的算力、KV 读写带宽都按保留比例缩减。因此 TTFT 的改善来自后段，而 TPOT 的改善有限——解码每步仍要遍历保留 token 的 KV，缩减比例与压缩率同阶，但基数小。</p>\n<p>把 TTFT 拆开看：</p>\n<div class=\"formula\">$$T_{\\text{TTFT}}\\approx T_{\\text{pre}}(L_p)+T_{\\text{rank}}+T_{\\text{reorder}}+T_{\\text{post}}(k)$$</div>\n<p>$T_{\\text{pre}}(L_p)$ 与不剪枝方案相同，$T_{\\text{rank}}$ 是累积分数排序，$T_{\\text{reorder}}$ 是一次性 KV 重排，$T_{\\text{post}}(k)$ 随后段保留 token 数 $k$ 下降。压缩率越高，$T_{\\text{post}}$ 越小，但 $T_{\\text{rank}}$ 与 $T_{\\text{reorder}}$ 不变，且 $L_p$ 越深 $T_{\\text{pre}}$ 越大。存在一个最优压缩率，使总 TTFT 最小；超过它，重排与排序的固定开销开始占主导。</p>\n<p>对 SLO 的直接含义：EvoCut 适合把 TTFT 目标压在预填后段的场景，例如交互式视觉问答的首 token 时限。若 SLO 主要约束 TPOT（流式长文生成），EvoCut 的贡献有限，应把预算让给解码侧的 KV 量化或投机解码。批大小下调会拉长排队时间，间接恶化 TTFT 的尾部分布，因此容量规划要把“统计缓存挤占导致的并发下降”计入 TTFT 的 P99，而不只看单请求的 $T_{\\text{TTFT}}$。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-22\">二十二 · 负载不对时的三种失效</h3>\n<p><strong>失效一：显存挤压。</strong>长视频或高分辨率输入下，$L_p \\cdot N_v \\cdot b$ 迅速膨胀，与 KV cache 争预算，调度器被迫下调批大小。表现为吞吐下降、排队变长，而单请求延迟未必变差——这是最隐蔽的一种，监控上只看 TTFT 会误判系统健康。判据是统计缓存占用与 KV cache 占用的比值，一旦接近同量级，就说明负载已超出 EvoCut 的舒适区。</p>\n<p><strong>失效二：选层不当的精度回退。</strong>剪枝点太浅，累积分数还没等到后层抬升就截断，等于退化成首层打分，相同压缩率下精度受损；剪枝点太深，缓存与 $T_{\\text{pre}}$ 都变大，收益被吃掉。选层需按模型深度调参，浅层剪枝收益大但误删风险高，这条权衡没有通用解，只能按模型与负载分布实测标定。</p>\n<p><strong>失效三：重排与后续计算不同步。</strong>一次性剪枝后 KV 重排若与后续层注意力计算未对齐，保留 token 的位置索引会错乱，解码出现一致性错误——输出重复、指代漂移。这类错误不体现在延迟指标上，只体现在答案质量上，且往往在长输出时才暴露。工程上要把重排做成原子步骤，重排完成前不释放后续层的计算依赖。</p>\n<p>三种失效的共同点是：它们都不改变“EvoCut 在合适负载上更快更准”这一结论，但会把不合适负载上的代价从延迟转移到显存、精度或一致性上。容量规划时应把请求按 $N_v$ 与输出长度分桶，对长视觉短输出的桶启用 EvoCut，对短视觉长输出的桶回退到不剪枝路径，避免用一套配置覆盖全部流量。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-23\">二十三 · 配方落地：分桶与回退</h3>\n<p>落地做法是把负载配方写成路由规则而非全局开关。第一维看 $N_v$：视觉 token 数超过阈值时，统计缓存占比高，需同时下调批大小上限或先做帧采样；低于阈值时 EvoCut 的缓存开销可忽略，可放心启用。第二维看输出长度：短输出（分类、短答）预填占主导，EvoCut 收益最大；长输出（推理链、长描述）解码占主导，收益摊薄，应回退。第三维看 query 与视觉内容的耦合强度：强耦合（指代明确、需要跨区域整合）演化明显，弱耦合（全局描述）演化平坦。</p>\n<p>回退路径要保留同一套 KV 布局与量化配置，只跳过统计缓存与剪枝步骤，使路由切换不触发重新编译或重新分配。批调度器按桶分配并发额度，把统计缓存的显存预留做成每桶的硬上限，超限即排队而非抢占其他桶的 KV。这样“负载不对”时的表现是可预期的降级，而不是隐式的显存溢出或精度漂移。</p>\n<p>一个具体工程判断：当监控发现某桶的统计缓存占用持续逼近其预留上限，且该桶的 TTFT P99 随批大小下调而恶化，说明该桶的 $N_v$ 分布已漂移出配方范围，应调整桶边界或对该桶关闭 EvoCut，而不是继续压缩批大小硬撑——后者会把显存压力转成排队延迟，SLO 反而更差。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-24\">二十四 · 负载错配时，EvoCut 的收益会先于精度一起蒸发</h3>\n<p>EvoCut 的负载配方有一个硬前提：请求必须是图像或视频加文本的 VLM 形态，且显著性在层间确有演化。若把纯文本请求或极短图像描述塞进这条路径，逐层记录视觉 token 注意力质量的开销照付，可剪枝对象几乎不存在，演化分数 $s_i=\\sum_{l=l_0}^{l_1}\\gamma^{l-l_0}a_i^{(l)}$ 的区分度被噪声淹没，top-k 保留集合与不剪枝几乎等价——省不下算力，却多背了一份统计缓存。反过来，长度分布极端偏斜时问题更尖锐：长视频或高分辨率输入使视觉 token 数暴涨，多层注意力统计的缓存随层数线性增长，直接挤占 KV cache 预算，批大小被迫下调，吞吐的损失可能盖过剪枝带来的预填后段算力节省。批大小的可行域因此不是由显存总量单独决定，而是由“KV cache + 多层统计缓存”的联合占用决定，后者在长输入下是主导项。</p>\n<p>剪枝层位置 $L_p$ 是第二个负载敏感点。浅层剪枝让后续绝大多数层只对保留 token 计算，收益最大，但此时累积显著性样本少，后续层才变重要的 token 极易被误删；深层剪枝统计更充分、误删风险低，可省下的层数变少，收益被压缩。这条折中曲线随模型深度移动：层数越深的 VLM 越适合把 $L_p$ 往后放，浅层模型则几乎没有腾挪空间。选层不当的后果不是渐进退化，而是在相同压缩率下出现精度回退——压缩率这个指标本身失去可比性，容量规划若按压缩率折算算力节省，会系统性高估吞吐。</p>\n<p>第三个失效条件是时序耦合。一次性剪枝后 KV 重排必须与后续层注意力计算严格同步，保留 token 的位置索引一旦错乱，解码一致性立刻受损，表现为输出重复、截断或与预填阶段语义漂移。这类错误不体现在 TTFT 上，却会在解码后段以长尾形式暴露，SLO 里若只约束首 token 延迟，就会漏掉这部分代价。可用下表把负载形态与主要代价对齐：</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>主要代价</th><th>典型失效</th></tr></thead><tbody><tr><td>短图像描述、低并发</td><td>统计缓存固定开销占比高</td><td>剪枝收益趋零，显存白占</td></tr><tr><td>长视频、高分辨率</td><td>多层统计缓存挤占 KV cache</td><td>批大小下调，吞吐反降</td></tr><tr><td>深层模型、浅剪枝点</td><td>误删后续层重要 token</td><td>同压缩率下精度回退</td></tr><tr><td>高并发、TTFT 敏感</td><td>KV 重排与后续层不同步</td><td>解码一致性受损</td></tr></tbody></table>\n<p>工程判断落在缓存预算与剪枝深度的联合调参上：先按目标批大小反推可分配给多层统计的显存上限，再在该上限内选尽可能深的 $L_p$，把误删风险压到可接受区间；若长输入占比高到统计缓存无法与 KV cache 共存，正确做法是下调压缩率或退回单层打分方案，而不是硬扛批大小。规模上限本质上由“层数 × token 数 × 统计精度”三者乘积约束，层数越多、token 越多，缓存越大，这条约束在负载配方里比任何精度指标都更早触顶。</p>\n<h3 id=\"alg-evocut-multilayer-sec-25\">二十五 · 硬件档位：按统计缓存而非算力选型</h3>\n<p>EvoCut 的部署选型有一个与常规推理服务相反的判断顺序：先算多层注意力统计缓存需要多少显存与带宽，再倒推能上什么卡。因为剪枝点集中在一层，后续层只对保留 token 计算，算力侧的压力反而随压缩率下降；真正卡住配置的是从第 1 层到剪枝层 $L_p$ 之间必须驻留的逐层视觉 token 注意力质量 $a_i^{(l)}$。这份统计的规模随层数线性增长、随视觉 token 数线性增长，在长视频或高分辨率输入下会直接与 KV cache 争夺同一块 HBM。</p>\n<p>由此得到档位划分的工程判据：在 SM100/SM103 这一代，单卡 HBM 容量决定了「统计缓存 + KV cache + 权重」三者能否共存。若视觉 token 数较大、$L_p$ 又取得较深，统计缓存占比上升，此时应优先选择 HBM 容量更大的档位（B300 相对 B200 的容量余量、GB300 NVL72 的单节点聚合显存），而不是选择峰值算力更高的档位——因为本算法的瓶颈不在 MMA 吞吐。反之，若输入以单图为主、视觉 token 数有限，统计缓存占比小，则算力档位的边际收益重新变得可见，此时 tcgen05 的 2-SM MMA 与 TMEM 路径才有意义。</p>\n<p>一个具体的配置思路：把「每请求统计缓存字节数」作为第一类容量指标写进容量规划表，与 KV cache 字节数并列，而不是把它当作临时缓冲区。举例来说，一个视频请求携带的视觉 token 数远高于单图请求，若按单图请求的统计缓存预算去配置批大小，长视频请求一到达就会触发显存挤压，表现为批大小被动下调、TTFT 抖动。工程上应把统计缓存按请求形态分档预留，而不是全局共享一个池。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-26\">二十六 · 并行拓扑：沿用原 LLM 切分，剪枝层是同步点</h3>\n<p>EvoCut 不引入新的并行维度。张量并行、流水线并行、专家并行的切分方式可以完全沿用原 LLM 的部署，因为剪枝发生在 LLM 内部某一层，剪枝前后的计算图与原模型同构，只是 token 维度变窄。这一点决定了拓扑设计的主要工作不是重新切分，而是处理剪枝层作为<b>全局同步点</b>带来的气泡。</p>\n<p>在流水线并行下，剪枝层 $L_p$ 落在某个 stage 上，该 stage 需要等待前面所有 stage 把逐层统计传完才能执行 top-k 与 KV 重排；剪枝之后的下游 stage 收到的 token 数骤降，算力占用出现台阶式下跌。若 $L_p$ 选得偏深，上游 stage 在剪枝前一直按全量 token 计算，气泡集中在上游；若 $L_p$ 选得偏浅，上游负担轻但误删风险上升——这正是前文所述「浅层剪枝收益大但风险高」在拓扑上的具体表现。伪代码层面的调度约束可写成：</p>\n<div class=\"formula\">$$\\text{stage}(L_p)\\ \\text{必须等}\\ \\sum_{l&lt;L_p}\\text{stats}(l)\\ \\text{就绪},\\ \\text{之后}\\ \\text{stage}&gt;\\!\\text{stage}(L_p)\\ \\text{按}\\ k\\ \\text{个 token 重排 micro-batch}$$</div>\n<p>在张量并行下，问题转为通信量：剪枝前的 all-reduce 按全量视觉 token 进行，剪枝后按保留 token 进行，通信量在 $L_p$ 处出现一次跳变。NVLink 5 的高带宽使这次跳变的绝对代价可控，但集合通信的排序与同步仍需在剪枝层显式插入屏障，否则不同 rank 可能对「保留哪些 token」产生不一致的判断。工程判断是：把 top-k 的决策放在单一 rank 或单一 stage 上做，再把保留索引广播出去，避免各 rank 各自排序带来的索引漂移。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-27\">二十七 · 量化方案：统计路径与计算路径分开对待</h3>\n<p>量化方案要区分两条路径。计算路径（剪枝后保留 token 的后续层矩阵乘）可以沿用原 LLM 部署已有的量化配置：NVFP4 或 FP8 的选择取决于原模型的量化精度与校准数据，EvoCut 不改变这一层的数值行为，因为剪枝只改变 token 数量，不改变每个 token 的数值范围。统计路径则不同：$a_i^{(l)}$ 是注意力质量，用于跨层累积与排序，它的数值精度直接决定 top-k 边界上的 token 是否被误删。</p>\n<p>这里的关键机制是排序的稳定性。演化分数 $s_i=\\sum_{l=l_0}^{l_1}\\gamma^{l-l_0}a_i^{(l)}$ 在低精度下累积会产生舍入误差，当第 $k$ 名与第 $k+1$ 名的分数接近时，量化噪声足以翻转保留集合。因此工程上应把统计量的累积放在较高精度（FP32 或至少 BF16 的累加器）中完成，只在最终写入缓存时降精度以节省带宽。这与「多模态全静态量化」那类把整条链路压到低比特的做法不同：EvoCut 的量化边界画在统计路径与计算路径之间。</p>\n<p>代价方面，统计缓存若以 BF16 存储，其带宽占用是 FP8 的两倍，而这份缓存要在剪枝前被反复读写（每层写入、剪枝时一次性读出做 top-k）。在长视频场景下，这份带宽开销会与 KV cache 的读写争抢 HBM 带宽，成为 TTFT 的实际限制项。一个可复现的做法是：统计缓存按层分块写入、剪枝时流式读出并即时累积，避免把全部层的统计同时物化在显存中——用带宽换容量，把峰值显存压到「单层统计 + 累积器」的量级。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-28\">二十八 · KV 策略：一次性重排与索引一致性</h3>\n<p>EvoCut 的 KV 策略优势在于「只重排一次」。剪枝点集中在一层，意味着 KV cache 的物理布局只需在 $L_p$ 处做一次压缩与重排，后续层按新的 token 数继续追加，不需要在每层都做搬移。这与逐层压缩方案形成鲜明对比：后者每层都要重写 KV 布局，重排代价随层数线性累积。EvoCut 把这份代价折叠成单点事件，代价可控。</p>\n<p>但单点事件也意味着单点风险。失败模式中明确列出：一次性剪枝后 KV 重排若与后续层注意力计算不同步，保留 token 的位置索引会错乱，影响解码一致性。机制上，这发生在重排写入与后续层读取之间存在竞态时——重排是异步的，而下一层的注意力计算可能已经按旧索引发起。工程上的对策是把重排做成显式的屏障操作：先完成保留索引的确定与广播，再完成 KV 的物理搬移，最后才允许后续层发起计算。索引表应与 KV 数据一起版本化，解码阶段的位置编码需按新索引重新映射，否则保留 token 的相对位置会整体偏移。</p>\n<p>容量上，剪枝释放的 KV 空间可以立即回收到批调度器，这是 EvoCut 提升吞吐的直接来源：预填后段算力随保留 token 数下降，同时 KV 占用下降使更多请求能进入同一批次。但回收时机必须晚于重排完成，否则会出现「空间已释放、数据仍在搬移」的越界。工程判断是把回收动作挂在重排屏障之后，而不是挂在 top-k 决策之后。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-29\">二十九 · 调度参数：批大小、剪枝层与压缩率的三角约束</h3>\n<p>调度参数之间存在硬约束三角：批大小受统计缓存占用约束，剪枝层深度 $L_p$ 决定统计缓存的层数维度，压缩率（保留 token 数 $B$）决定剪枝后的算力与 KV 占用。三者不能独立调优。加大批大小会推高统计缓存峰值；加深 $L_p$ 会线性增加统计缓存的层数；提高压缩率会降低剪枝后算力但抬高误删风险。</p>\n<p>可复现的配置思路是按以下顺序定参：先按目标 SLO 的 TTFT 上限确定可接受的预填时长，再据此反推剪枝后需保留的 token 数 $B$（因为预填后段算力正比于 $B$）；然后按模型深度选择 $L_p$，使统计缓存的层数维度落在显存预算内，同时尽量靠前以放大收益；最后用剩余显存反推批大小。这个顺序把「精度风险」放在 $L_p$ 的选择上，把「吞吐」放在批大小上，两者解耦。</p>\n<p>连续批处理下的一个具体机制：剪枝层是批次内所有请求的共同屏障，因此调度器应尽量把剪枝层对齐的请求编入同一批次，避免一个请求在剪枝层等待另一个尚未到达该层的请求。若请求形态混合（单图与视频同批），统计缓存占用差异大，应按请求形态分桶调度，而不是按到达顺序混排。表格给出参数间的定性关系：</p>\n<table class=\"mini\"><thead><tr><th>参数</th><th>上调的收益</th><th>上调的代价</th><th>约束来源</th></tr></thead><tbody><tr><td>批大小</td><td>吞吐上升</td><td>统计缓存峰值上升，挤占 KV</td><td>HBM 容量</td></tr><tr><td>剪枝层 $L_p$ 加深</td><td>误删风险下降</td><td>统计缓存层数维度线性增长，上游气泡变大</td><td>显存与流水线同步</td></tr><tr><td>压缩率提高（$B$ 减小）</td><td>剪枝后算力与 KV 占用下降</td><td>精度回退风险上升</td><td>精度验收</td></tr><tr><td>统计精度提高</td><td>top-k 边界稳定</td><td>统计缓存带宽翻倍</td><td>HBM 带宽</td></tr></tbody></table>\n<p>这张表的作用不是给出数值，而是标明每个旋钮的代价归属：容量型代价归 HBM，带宽型代价归统计路径，精度型代价归 $L_p$ 与 $B$。工程上遇到 TTFT 超标时，应先判断是容量挤压还是带宽争抢——前者调批大小与分桶，后者调统计精度与分块流式读出，两者的处置方向相反，混调会互相抵消。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-30\">三十 · 可复现配置的落地检查项</h3>\n<p>把上述配方落成可复现配置，需要一组可观测的检查项，而不是一组固定数值。第一项是统计缓存的峰值占用与 KV cache 占用的比值，这个比值决定了批大小是否被统计缓存而非 KV 约束——若比值偏高，说明配置已进入 EvoCut 特有的容量瓶颈区。第二项是剪枝层前后的 token 数台阶，用于验证重排是否按预期生效，以及后续层是否真的只对保留 token 计算。第三项是保留索引的版本一致性，用于捕捉前文所述的索引错乱失败模式。</p>\n<p>第四项是 top-k 边界附近的分数量化噪声幅度：把第 $k$ 名与第 $k+1$ 名的分数差与统计精度下的舍入误差比较，若两者同量级，说明当前精度不足以稳定保留集合，需要提高统计累加精度或调整 $B$ 使边界落在分数间隙更大的位置。这一检查把「精度回退」从验收阶段的被动发现，前移为部署阶段的主动判据。</p>\n<p>最后一项是剪枝层与流水线 stage 边界的对齐关系。若 $L_p$ 恰好落在 stage 边界上，同步屏障与 stage 切换可以合并，气泡最小；若落在 stage 内部，则该 stage 需要额外的内部屏障，气泡放大。工程判断是：在模型深度允许的范围内，优先把 $L_p$ 对齐到 stage 边界，用拓扑对齐换取同步开销的下降，而不是单纯按注意力演化轨迹的最优位置选层——后者在精度上更优，但在流水线部署下会引入可观测的 TTFT 抖动。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-31\">三十一 · 剪枝层深度与统计缓存的预算折中：EvoCut 配方的边界条件</h3>\n<p>这套配方真正脆弱的地方不在量化或并行拓扑——那两项可以照搬原 LLM 部署——而在剪枝层深度 $L_p$ 与多层注意力统计缓存之间的耦合。演化分数 $s_i=\\sum_{l=1}^{L_p} w_l \\cdot a_i^{(l)}$ 要求在第 $L_p$ 层之前逐层留存视觉 token 的注意力质量，缓存规模随 $L_p$、视觉 token 数 $N_v$ 与头数线性增长；而 $L_p$ 越浅，被误删的“后续才变重要”的 token 越多，压缩收益越大、精度风险也越大。工程上应把 $L_p$ 当作与批大小联调的旋钮：先固定一个可接受的统计缓存预算，反推 $L_p$ 的上界，再在该上界内取使 $s_i$ 排序最稳定的层。</p>\n<table class=\"mini\"><thead><tr><th>档位</th><th>$L_p$ 取向</th><th>主要代价</th><th>失效信号</th></tr></thead><tbody><tr><td>浅剪枝</td><td>靠近前段层</td><td>统计缓存小、后段算力降幅大</td><td>相同压缩率下精度回退</td></tr><tr><td>深剪枝</td><td>靠近中后段层</td><td>缓存占用高、挤占 KV cache</td><td>批大小被迫下调、TTFT 抖动</td></tr></tbody></table>\n<p>失效条件可以写成一条硬约束：统计缓存与 KV cache 共享同一块 HBM，当 $N_v$ 随长视频或高分辨率输入上升时，缓存项会先于权重项触顶，此时唯一可调的是批大小，而批大小下调直接压低吞吐、拉高单位 token 成本。因此配方中必须显式保留一条降级路径——输入分辨率或帧数超阈值时改用更深但更稀疏的采样，或退回单层打分以释放缓存——而不是让调度器在 OOM 边缘反复重试。</p>\n<p>另一个被低估的代价是 KV 重排的时序正确性：一次性剪枝后，保留 token 的位置索引必须在后续层注意力计算启动前完成重写，若重排与计算不同步，索引错乱会以解码不一致的形式暴露，且难以从日志定位。配方应把重排作为剪枝层的同步屏障，并在该层禁用跨步流水，用一次可控的停顿换取索引一致性；由于剪枝点集中在一层，这次停顿的摊销成本远低于逐层剪枝方案。</p>\n<h3 id=\"alg-evocut-multilayer-sec-32\">三十二 · 多层统计缓存的显存账本</h3>\n<p>EvoCut 的显存代价不在剪枝本身，而在剪枝之前那段“只看不删”的观测窗口。设视觉 token 数为 $N_v$、观测层区间为 $[l_0,l_1]$、每层每 token 需保留一个注意力质量标量（实际实现常按 head 或 head-group 聚合后降维存储），则统计缓存的最低温存占用可写成</p>\n<div class=\"formula\">$$M_{\\text{stat}} \\approx N_v \\cdot (l_1-l_0+1) \\cdot H_g \\cdot b$$</div>\n<p>其中 $H_g$ 为聚合后的头组数、$b$ 为每元素字节数。关键在于这个量与 KV cache 是<strong>并行占用</strong>的：预填阶段 KV cache 本身正随序列长度线性膨胀，统计缓存再叠一层，等于在同一个显存池里开了第二本账。工程上的直接后果是批大小被压：连续批处理调度器按剩余显存反推可接纳的并发请求数，统计缓存每涨一档，可并行的图像/视频请求就少一批。长视频输入是放大器——$N_v$ 随帧数与分辨率上升，$M_{\\text{stat}}$ 与 KV 同时被推高，二者争夺同一预算，最先崩的往往不是算力而是显存容量。</p>\n<p>具体机制上，缓解手段是“降维而非全存”：只保留聚合后的头组均值或按 token 的范数代理，把 $H_g$ 从全头数压到个位数；或对观测层做分段采样，只在 $l_0$、中间层、$l_1$ 三处落盘，用插值近似中间层轨迹。代价是演化分数的分辨率下降，误删风险回升——这是显存与精度之间的直接兑换，没有免费选项。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-33\">三十三 · 带宽：统计写入与 KV 重排的双重压力</h3>\n<p>显存容量只是静态约束，真正拖慢预填的是带宽。观测窗口内每层都要把视觉 token 的注意力质量写出，写入带宽需求约为 $N_v \\cdot H_g \\cdot b \\cdot f_{\\text{layer}}$（$f_{\\text{layer}}$ 为层推进速率）。这部分流量与正常的前向计算争抢 HBM 带宽，在 prefill 阶段本就带宽敏感的 GEMM 上形成干扰，表现为 TTFT 的尾部长尾。</p>\n<p>更重的一笔在剪枝点：一次性剪枝要求把保留 token 的 KV 从原位置重排到连续布局，等价于对 $N_v$ 规模的 KV 做一次 gather-scatter。重排带宽量级为 $k \\cdot d_{\\text{kv}} \\cdot b$（$k$ 为保留数、$d_{\\text{kv}}$ 为每 token KV 维度），且必须与后续层的注意力计算严格同步——若重排未完成就进入下一层，位置索引错乱会直接污染解码一致性，这是材料中明确列出的失败模式。工程判断是：把重排做成一次性的、集中的、可与下一层预取重叠的拷贝，而不是逐层增量搬迁；剪枝点集中在一层正是为了让这笔带宽只付一次，这是 EvoCut 相对逐层压缩方案在系统层面的核心优势。</p>\n<p>例子：一段高分辨率多帧视频进入 VLM，$N_v$ 处于高位，观测窗口内每层写统计、剪枝点再做全量 KV 重排，两笔带宽叠加使 prefill 后段出现明显带宽饱和；此时即便算力空闲，TTFT 也被带宽钉住。把观测层改为三点采样后，写入流量下降，但需接受演化分数精度损失。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-34\">三十四 · 通信：并行拓扑下的统计聚合</h3>\n<p>当模型按张量并行（TP）切分时，注意力质量天然分布在多个 rank 上：每个 rank 只持有部分 head 的注意力输出。要得到全局可比的演化分数 $s_i$，必须在剪枝点之前做一次跨 rank 的归约。若按 token 维度做 all-reduce，通信量为 $N_v \\cdot H_g \\cdot b$ 量级，随 $N_v$ 线性增长；在 NVLink 域内这笔开销可被带宽吸收，但跨节点（如 NVL72 机架外的 PP/EP 组合）时延不可忽略。</p>\n<p>机制上的优化是“本地先聚合、全局后归约”：各 rank 先在本地对 head 组求和降维，只把降维后的 per-token 标量送上 all-reduce，把通信量压到 $N_v \\cdot b$ 量级。剪枝决策本身需要全局一致的保留集合，因此 top-$k$ 必须在归约后统一执行，各 rank 再按同一索引本地重排自己的 KV 分片——这要求保留索引的广播与重排的同步屏障，是剪枝点处一次显式的集合通信。规模上去后，通信先崩的位置通常在剪枝点的同步屏障：所有 rank 必须等最慢的那个完成统计写入才能进入 top-$k$，尾延迟由此产生。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-35\">三十五 · 功耗与热：观测窗口的持续占用</h3>\n<p>EvoCut 的功耗特征不是峰值冲高，而是<strong>观测窗口拉长了高功耗驻留时间</strong>。多层统计要求模型在剪枝前完整跑过 $[l_0,l_1]$ 的所有层且不能提前丢弃 token，意味着这段区间内计算与带宽都维持在高位，功耗曲线在该窗口内呈平台状而非快速衰减。对风冷或液冷机架而言，持续平台比瞬时尖峰更难压：它抬高了平均功耗，压缩了同一机架内其他任务的功耗预算。</p>\n<p>工程上的对冲是把观测窗口与批调度错峰：在统计缓存占用高的请求之间插入已完成剪枝、进入解码阶段的轻负载请求，用解码的低算力占比平滑整机功耗曲线。代价是调度复杂度上升，且解码请求的 KV 驻留会反过来挤压统计缓存的空间——功耗与显存在这里再次耦合。规模上去后，功耗先崩的场景通常是长视频高并发：观测窗口的平台功耗叠加多请求并发，使机架功耗封顶被迫触发降频，反过来拉长 TTFT。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-36\">三十六 · 尾延迟：剪枝点作为全局同步点</h3>\n<p>把剪枝集中在一层，收益是 KV 重排只付一次，代价是这一层变成整个预填路径上的<strong>全局同步点</strong>。所有并发请求的剪枝决策、索引广播、KV 重排都汇聚于此，任何一条慢路径都会把尾延迟拉长。用排队视角看，剪枝点的服务时间由三部分组成：统计归约、top-$k$ 选择、KV 重排拷贝，三者串行且都随 $N_v$ 增长，因此 P99 TTFT 对该点的敏感度远高于均值。</p>\n<p>具体机制上的缓解是“决策与拷贝分离”：top-$k$ 只需标量分数，可在归约完成后立即算出保留索引并广播，让后续层的注意力计算先按索引走；KV 重排拷贝则异步推进、与下一层计算重叠，只要保证被后续层读取前完成即可。这把同步点从“重排完成”前移到“索引确定”，显著压缩尾延迟的暴露面。失败模式仍是同步失配：索引已广播而拷贝未落地时若后续层直接读取，位置错乱即刻发生，因此需要一个显式的完成栅栏，栅栏的粒度决定了重叠的收益上限。</p>\n<p>例子：多请求并发下，某请求因 $N_v$ 偏大在剪枝点耗时最长，成为整批的尾延迟决定者；调度器若按均值估算容量，会低估 P99 而违反 SLO。正确做法是把剪枝点耗时按 $N_v$ 分档建模，对超长输入单独限流或降级观测层数。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-37\">三十七 · 规模上去以后哪里先崩</h3>\n<p>把五本账放在一起排序，崩溃顺序随规模呈现清晰的层次。第一层是<strong>显存容量</strong>：统计缓存与 KV cache 共享预算，$N_v$ 与层数同时上升时，批大小被迫下调，吞吐先掉。第二层是<strong>剪枝点带宽与同步</strong>：即便显存够，KV 重排与统计写入的带宽叠加会把 TTFT 尾部拉长，P99 先违约。第三层是<strong>通信屏障</strong>：TP/EP 规模扩大后，剪枝点的全局归约与索引广播的时延占比上升，跨节点部署时尤为明显。第四层才是<strong>功耗封顶</strong>：观测窗口的平台功耗在多请求并发下触发降频，反过来放大前三层的时延。</p>\n<p>对应的工程判断是分层设防而非统一调参：显存层用统计降维与观测层采样换空间；带宽层用决策/拷贝分离把重排藏进计算；通信层用本地聚合降维压缩 all-reduce 量级；功耗层用批内混合负载平滑曲线。剪枝层深度 $L_p$ 的选择则是贯穿所有层的旋钮——浅层剪枝让后续层只算保留 token，算力与带宽收益最大，但观测窗口短、演化轨迹采样不足，误删风险最高；深层剪枝统计更充分但收益被压缩。规模越大，越应把 $L_p$ 往深处挪以换取稳定性，用收益换尾延迟的可预测性，这是 EvoCut 在系统层面的核心取舍。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-38\">三十八 · 统计缓存的显存墙与带宽账</h3>\n<p>EvoCut 的代价不在剪枝那一层，而在剪枝之前的每一层。为了得到跨层累积显著性，系统必须在预填阶段为每个视觉 token 逐层保留注意力质量，直到预设剪枝层 $L_p$ 才一次性结算。设批内视觉 token 总数为 $N_v$、层数为 $L_p$、每 token 每层统计量占 $b$ 字节，则统计缓存规模为</p>\n<div class=\"formula\">$$M_{\\text{stat}} = N_v \\cdot L_p \\cdot b$$</div>\n<p>这一项与 KV cache 争夺同一块 HBM：长视频或高分辨率输入把 $N_v$ 推高，$L_p$ 又随模型深度线性增长，缓存预算被挤占后只能下调批大小，吞吐随之塌陷。更隐蔽的是带宽账——逐层写统计量意味着每层都要把 $N_v \\cdot b$ 的数据搬进搬出，这部分流量不产生任何有效 FLOPs，却与 KV 读写、权重加载抢同一份 HBM 带宽。工程上应把统计量压到最低精度（如单通道 FP16 或 INT8 量化后的注意力质量），并把写入与当层注意力计算融合，避免额外的 kernel launch 与中间张量落盘。</p>\n<h3 id=\"alg-evocut-multilayer-sec-39\">三十九 · 剪枝层深度是吞吐与精度的单旋钮</h3>\n<p>剪枝点 $L_p$ 决定了两件事：统计缓存的上界，以及预填后段能省下多少算力。$L_p$ 越浅，后续 $L-L_p$ 层只对保留 token 计算，节省的注意力与 FFN 算力越多，TTFT 下降越明显；但浅层注意力尚未分化，演化分数 $s_i$ 的信噪比低，误删后续才变重要的 token 的风险陡增，相同压缩率下精度回退。反之 $L_p$ 越深，统计缓存越大、剪枝收益越小，方案退化为“几乎不省”。这是一个没有免费午餐的折中，必须按模型深度实测标定，不能跨模型套用同一比例。对深层 VLM，可考虑把 $L_p$ 设在注意力模式开始稳定的中后段，并用少量校准样本验证保留集合与全量注意力 top-k 的重合度。</p>\n<h3 id=\"alg-evocut-multilayer-sec-40\">四十 · 一次性重排的同步陷阱与尾延迟</h3>\n<p>剪枝点集中在一层的好处是 KV 重排只需一次，代价可控；坏处是把正确性押在这次重排上。重排要同时改写 KV 张量布局、位置索引与后续层的注意力掩码，三者若与后续层计算不同步，保留 token 的位置索引就会错乱，解码一致性被破坏——这类错误不报错，只表现为输出漂移。尾延迟也集中在这里：重排是一次全局 gather/scatter，长序列下其耗时随保留 token 数线性上升，且无法与下一层计算重叠，成为预填路径上的尖峰。实现上应把重排做成原地压缩并立即释放被删 token 的 KV 页，让后续层的注意力 kernel 直接读到连续布局，避免二次拷贝。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先崩的位置</th><th>工程对策</th></tr></thead><tbody><tr><td>视觉 token 数 $N_v$ 上升</td><td>统计缓存挤占 KV cache，批大小下调</td><td>统计量低精度化、与当层计算融合</td></tr><tr><td>模型层数加深</td><td>$L_p$ 增大，缓存与带宽同步上涨</td><td>按深度标定剪枝点，限制统计层窗口</td></tr><tr><td>批大小上升</td><td>重排 gather 的尾延迟尖峰</td><td>原地压缩、及时释放 KV 页</td></tr></tbody></table>\n<p>结论落在选层与预算的联合约束上：先按 HBM 预算反解可承受的 $N_v \\cdot L_p$，再在该约束内挑精度损失最小的剪枝层，而不是先定压缩率再补显存。</p>\n<h3 id=\"alg-evocut-multilayer-sec-41\">四十一 · 精度回退的定位：剪枝层选错与统计口径错位</h3>\n<p>EvoCut 的精度失败几乎不会以“整体掉点”这种笼统形态出现，而是集中在两类可定位的病灶上。第一类是剪枝层深度 $L_p$ 选得过浅：演化分数 $$s_i=\\sum_{l=l_0}^{l_1}\\gamma^{l-l_0}\\,a_i^{(l)}$$ 在浅层截断时，累积窗口太短，$\\gamma$ 衰减还来不及把后续层才抬头的 token 拉进保留集合，于是这些 token 在预填阶段被一次性剔除，后续层再想恢复已无可能。第二类是统计口径错位——记录注意力质量时用了未归一化的 logits 而非 softmax 后的概率质量，或者把跨层统计的 token 顺序与 KV 重排后的位置索引对不上，导致保留集合本身没错、但落到 KV 上的位置错了。</p>\n<p>诊断这两类问题的工程手段是分层探针，而不是看端到端指标。做法是在剪枝层前后各挂一个轻量钩子，对同一批校准请求分别计算“剪枝前全量 token 的下一层注意力分布”与“剪枝后保留 token 的注意力分布”，比较两者的 top-$k$ 重合率：重合率高说明保留集合抓住了后续层真正要用的 token，重合率骤降则指向 $L_p$ 过浅。对位置索引错乱，则直接比对重排前后每个保留 token 的 position id 序列是否单调、是否与文本 token 的相对位置一致。代价上，这套探针只在离线校准阶段跑，不进入在线路径；但它要求缓存多层注意力统计，显存占用随层数与 token 数线性增长，长视频输入下这笔开销会直接挤压 KV cache 预算。</p>\n<p>具体例子：一个 32 层 VLM，若把 $L_p$ 设在第 4 层，演化窗口只覆盖前四层，浅层剪枝收益大（预填后段算力立即下降）但误删风险最高；把 $L_p$ 推到第 12 层，窗口变长、精度更稳，代价是前 12 层仍要按全量 token 计算并缓存统计，TTFT 的下降被推迟。选层本质是在“早剪省算力”与“晚剪保精度”之间移动工作点，而这个工作点必须按模型深度逐档标定，不能跨模型复用。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-42\">四十二 · OOM 的真实来源：统计缓存与 KV cache 争抢同一块显存</h3>\n<p>EvoCut 的 OOM 很少是权重或激活爆掉，绝大多数是多层注意力统计缓存与 KV cache 在同一显存池里互相挤压。统计缓存的规模量级可以写成 $M_{\\text{stat}}\\approx L_p \\cdot N_v \\cdot b$，其中 $N_v$ 是视觉 token 数、$b$ 是每 token 每层的统计字节数（注意力质量的存储精度决定 $b$）。当输入从单图变成高分辨率多图或长视频，$N_v$ 上升一个量级，$M_{\\text{stat}}$ 随之膨胀，而 KV cache 的预算是按最大并发批静态预留的，两者相加就越过显存上限。</p>\n<p>监控上要盯的不是“显存使用率”这个聚合值，而是把显存拆成三段分别打点：权重常驻、KV cache 实际占用、统计缓存峰值。只有三段分开看，才能判断 OOM 是批太大还是统计缓存失控。回滚策略相应地分两级：一级是降批，把 batch size 下调到统计缓存峰值加 KV 预算仍有余量的档位；二级是缩短统计窗口，把 $L_p$ 前移或对视觉 token 做分组采样统计，用精度换显存。前者不改变算法语义，后者改变保留集合的统计基础，属于有损回滚，必须配合精度探针确认重合率没有跌破阈值。</p>\n<p>工程判断上有一条硬约束：统计缓存必须是“剪枝即释放”的生命周期。剪枝层执行完一次性剪枝与 KV 重排后，多层统计已经没有用途，若框架把它挂在请求上下文里直到解码结束才回收，长请求会把这份本可释放的显存一直占着，等效于把 KV cache 的有效容量砍掉一块。这一点在多并发场景下比单请求更致命，因为每个活跃请求都持有一份统计。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-43\">四十三 · 批抖动：批大小被统计缓存钉死后的调度退化</h3>\n<p>连续批处理的前提是新请求能随时插入、完成的请求能随时退出，批的组成在时间上是流动的。EvoCut 破坏了这一前提的一半：批大小受多层注意力统计缓存占用约束，而统计缓存的生命周期覆盖从预填开始到剪枝层执行完毕的整段，这段时间里批的显存水位是刚性的、不可压缩的。结果是调度器看到一个“显存暂时不可用”的窗口，新请求被挡在门外，已入批的请求又因为剪枝点集中在一层而呈现同步的阶段性负载——预填前段全量计算重、剪枝后段轻，批内请求若处在不同阶段，算力利用就会出现锯齿。</p>\n<p>诊断批抖动要看两个派生指标：批组成的变化频率，以及批内请求所处阶段的方差。前者低、后者高，说明批被统计缓存锁死、内部阶段错位；两者都低但 TTFT 分位数抬高，说明是剪枝层本身的同步屏障在拖时间。缓解手段是把剪枝层做成批内可异步的检查点：不同请求在不同时刻到达各自的 $L_p$，各自独立重排 KV，而不是等整批一起过剪枝层。代价是 KV 重排从“一次集中操作”变成“多次分散操作”，重排本身的内存搬运开销上升，但换来了批的流动性。</p>\n<p>具体例子：一个混合长短请求的批，长视频请求的 $N_v$ 远大于图文请求，统计缓存峰值由长请求决定，短请求被迫陪着等长请求的剪枝窗口结束才能插入，短请求的 TTFT 被无谓拉长。按请求形态分池、把长视频请求单独成批，是比统一降批更精细的回滚路径。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-44\">四十四 · 路由不均与尾延迟尖刺：剪枝层成为同步屏障</h3>\n<p>EvoCut 把剪枝集中在一层，好处是 KV 重排只做一次、代价可控，坏处是这一层成了整个预填路径上的同步屏障。所有进入该层的请求都必须先完成统计累积、再执行 top-$k$ 选择、再重排 KV，三段串行且都依赖前面所有层的注意力结果，任何一段的抖动都会放大成尾延迟尖刺。尖刺的来源通常不是平均负载，而是路由不均：视觉 token 的显著性分布高度偏斜，少数请求的保留集合边界模糊（第 $B$ 名与第 $B+1$ 名分数接近），top-$k$ 选择在这些请求上更耗时，或者重排时保留 token 的位置跨度大、搬运不连续。</p>\n<p>监控尾延迟要把剪枝层单独切出来打点，记录该层的排队时间、top-$k$ 选择耗时、KV 重排搬运量三个分量，而不是只看整层耗时。若排队时间占比高，是同步屏障问题，解法是让剪枝层按请求粒度流水化；若搬运量异常大，是保留集合空间分布散乱，解法是对保留 token 做位置压缩或分块重排。公式上可以用一个简单的判据：当第 $B$ 名与第 $B+1$ 名的演化分数差 $\\Delta s$ 小于某个相对阈值时，标记该请求为“边界模糊”，对其采用更保守的保留数或走非剪枝路径。</p>\n<p>回滚上，尾延迟尖刺的第一道闸是请求级降级：对边界模糊或超长视觉输入的请求，跳过 EvoCut 剪枝、走全量 token 路径，牺牲该请求的算力换整批的 SLO 稳定。第二道闸是全局熔断：当剪枝层的排队时间分位数连续超过阈值，临时把 $L_p$ 后移或关闭剪枝，让系统退回单层打分或全量路径。这两道闸都必须能在线切换且不重启服务，因为尖刺是瞬态的，等人工介入已经错过窗口。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-45\">四十五 · 解码一致性：KV 重排与后续层不同步的隐性错误</h3>\n<p>最隐蔽的失败模式不在预填指标上，而在解码一致性上。一次性剪枝后 KV 重排若与后续层注意力计算不同步，保留 token 的位置索引会错乱——重排把 token 搬到新位置，但后续层的注意力掩码、位置编码或 KV 指针仍按旧索引寻址，于是模型看到的是一组“内容对、位置错”的 token。这类错误在预填阶段往往不报错、不崩，只是让生成结果的语义漂移，端到端指标上看像精度问题，实际是索引一致性缺陷。</p>\n<p>诊断方法是构造一组“重排不变性”测试：对同一输入，分别在开启与关闭剪枝（保留数设为全量）两种配置下跑贪心解码，比较前若干步的 logits 分布。若关闭剪枝时两者一致、开启剪枝后出现系统性偏移，则问题在重排路径而非剪枝准则本身。进一步可以把重排前后的 KV 张量按 token id 做对齐比对，确认每个保留 token 的 key/value 确实跟着它的 position id 一起搬了，而不是只搬了数据没搬元信息。</p>\n<p>工程代价上，保证一致性需要在重排时同步更新三类元数据：KV 张量的物理布局、注意力掩码的列索引、位置编码的偏移量。任何一类漏更新都会引入静默错误，而这三类元数据分散在框架的不同层（KV manager、attention kernel、position embedding），跨层同步本身就是易错点。回滚策略是把重排做成可关闭的开关，并在开关切换时清空所有在途请求的缓存，避免新旧索引混用；同时把重排后的首次解码步作为一致性校验点，一旦 logits 与预期路径偏离超过阈值，立即丢弃该请求并走全量重算。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-46\">四十六 · 监控面板与回滚阶梯的落地形态</h3>\n<p>把上述失败模式收拢成一套可运维的面板，核心是四个分层的打点集合，而不是一张大而全的仪表盘。第一层是资源层：权重、KV cache、统计缓存三段显存分开计量，配一条“统计缓存峰值占 KV 预算比例”的派生曲线，这条曲线越过阈值就是 OOM 的前兆。第二层是算法层：剪枝层前后的 top-$k$ 重合率、边界模糊请求占比、保留 token 的空间跨度分布，这三项直接对应精度回退与尾延迟尖刺。第三层是调度层：批组成变化频率、批内阶段方差、剪枝层排队时间分位数。第四层是一致性层：重排不变性测试的通过率与首次解码步的 logits 偏移量。</p>\n<p>回滚阶梯按代价从低到高排成四级，每级都有明确的触发条件与语义影响。<ul><li>一级：降批。触发条件是统计缓存峰值加 KV 预算逼近显存上限；语义不变，只损失吞吐。</li><li>二级：缩短统计窗口或前移 $L_p$。触发条件是重合率跌破阈值或统计缓存持续高位；有损，保留集合的统计基础变弱，需配合精度探针。</li><li>三级：请求级跳过剪枝。触发条件是边界模糊请求占比升高或尾延迟尖刺；单请求退化到全量路径，保护整批 SLO。</li><li>四级：全局关闭剪枝并清空在途缓存。触发条件是重排一致性校验连续失败或剪枝层排队时间失控；系统退回全量 token 路径，EvoCut 的收益归零但正确性恢复。</li></ul></p>\n<p>这套阶梯的关键设计约束是每一级都必须能在不重启进程的前提下切换，因为触发条件大多是瞬态的，重启带来的冷启动会把一次尖刺放大成一次服务中断。另一个约束是回滚必须携带缓存失效语义：任何改变保留集合或位置索引的切换，都要让在途请求的统计缓存与 KV 重排结果作废，否则新旧语义混用正是解码一致性错误的温床。最后一条工程判断是，四级回滚不应由人工逐级判断，而应由一致性层与调度层的分位数指标自动驱动，人工只负责标定阈值与审阅回滚日志——因为 EvoCut 的失败模式大多发生在剪枝层这一个点上，等人工看到端到端指标异常时，错误已经沿着后续层扩散出去了。</p>\n<h3 id=\"alg-evocut-multilayer-sec-47\">四十七 · 同族谱系：四类判据的分水岭</h3>\n<p>把 EvoCut 放进同族算法里，先要认清分水岭不在压缩率，而在“判据取自哪一段数据流”。视觉侧打分（VPRune 一类）在视觉编码器输出处就决定去留，判据是图像自身的特征显著性，LLM 尚未介入；近似误差判据（ApET）在合并动作前后比较注意力响应的偏移量，做贪心合并而非硬删；熵与 sink 修正判据（ERA）用注意力分布的熵值加 sink token 修正做联合打分，本质仍是单层或浅层的分布统计；EvoCut 的判据是跨层累积量，即把视觉 token 在第 $l_0$ 到 $l_1$ 层的注意力质量按层权重加权求和，再一次性决定保留集合。四者的差别直接决定三个工程属性：判据需要多少额外状态、剪枝动作是删还是并、剪枝点落在流水线的哪一段。视觉侧打分不占 LLM 显存，但看不见语言侧需求；合并类判据省 token 数却引入合并后的表示偏移，且贪心过程本身有串行开销；熵判据计算便宜，但对“早期不显著、后续层才被文本查询激活”的 token 天然失明；EvoCut 用缓存换判据质量，代价是显存与带宽。</p>\n<div class=\"formula\">$$s_i=\\sum_{l=l_0}^{l_1}\\gamma^{l-l_0}\\,a_i^{(l)},\\quad \\text{keep}=\\text{top-}k\\left(\\{s_i\\}\\right)$$</div>\n<p>式中 $\\gamma$ 是层间衰减因子，控制深层统计对最终分数的贡献权重；$\\gamma$ 取 1 即等权累积，取小于 1 则偏向浅层。这个参数与剪枝层深度 $l_1$ 共同构成 EvoCut 的两个调参旋钮，也是它与单层方案最实质的接口差异——单层方案没有 $\\gamma$，只有一个层的选择。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-48\">四十八 · 决策表：按约束选算法</h3>\n<p>选型不该从“哪个精度高”入手，而应从“哪个约束先撞墙”入手。下表按工程约束给出首选与次选，判据列写明该选择成立的前提。</p>\n<table class=\"mini\"><thead><tr><th>约束场景</th><th>首选</th><th>次选</th><th>成立前提</th></tr></thead><tbody>\n<tr><td>显存吃紧、KV cache 已接近上限</td><td>VPRune 类视觉侧打分</td><td>ERA 熵判据</td><td>可接受视觉侧误删带来的精度损失</td></tr>\n<tr><td>TTFT 是唯一 SLO，预填算力是瓶颈</td><td>EvoCut</td><td>ApET 合并</td><td>多层统计缓存不挤占 KV 预算</td></tr>\n<tr><td>显著性跨层演化明显、层数深</td><td>EvoCut</td><td>ERA</td><td>剪枝层深度可按模型深度调参</td></tr>\n<tr><td>不允许硬删、要求表示连续性</td><td>ApET 合并</td><td>EvoCut 降压缩率</td><td>合并的串行贪心开销可被批并行摊薄</td></tr>\n<tr><td>长视频、token 基数极大</td><td>VPRune 或 ERA</td><td>EvoCut 浅层剪枝</td><td>多层统计缓存规模随 token 数线性增长，需先算预算</td></tr>\n<tr><td>解码阶段带宽受限、需减 KV 读取</td><td>EvoCut</td><td>逐层压缩</td><td>一次性剪枝后 KV 重排与后续层同步</td></tr>\n</tbody></table>\n<p>表里最容易被误读的一行是“长视频”。EvoCut 的判据质量随层数增加而增益，但缓存开销是 $\\mathcal{O}(L_p \\cdot N_v)$，$N_v$ 为视觉 token 数、$L_p$ 为剪枝层深度。长视频把 $N_v$ 推到很大，缓存项会与 KV cache 直接争夺同一块 HBM，此时 EvoCut 的优势被显存压力抵消，浅层剪枝（减小 $L_p$）是唯一能同时保住判据与预算的折中，但浅层剪枝正是误删风险最高的区间。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-49\">四十九 · 适用条件的量化判据</h3>\n<p>把“适合 EvoCut”翻译成可计算的判据，需要三个量：演化幅度、缓存预算比、剪枝层风险。演化幅度可用同一 token 在浅层与深层的注意力质量比值分布来刻画——若大量 token 的 $a_i^{(l_1)}/a_i^{(l_0)}$ 显著偏离 1，说明单层打分必然误判，EvoCut 的跨层累积才有信息增益；若比值集中在 1 附近，显著性不演化，单层方案与 EvoCut 等价，多付的缓存纯属浪费。缓存预算比定义为多层统计缓存占用与 KV cache 预算之比，超过某个阈值就必须下调批大小，而批大小下调对吞吐的伤害往往大于精度收益。剪枝层风险则是浅层剪枝的误删率与深层剪枝的收益衰减之间的权衡：剪枝点越浅，后续层省下的算力越多（收益按剩余层数线性放大），但参与累积的层数越少，判据越接近单层。</p>\n<div class=\"formula\">$$\\text{gain}\\approx \\frac{L-L_p}{L}\\cdot\\Delta_{\\text{acc}},\\quad \\text{cost}\\approx \\frac{L_p\\cdot N_v\\cdot d}{M_{\\text{kv}}}$$</div>\n<p>第一式说明收益由剪枝点之后的剩余层数比例与精度增益 $\\Delta_{\\text{acc}}$ 共同决定；第二式说明代价由缓存元素数（层数 × token 数 × 每 token 统计维度 $d$）与 KV 预算 $M_{\\text{kv}}$ 的比值决定。两式相除即为选型的经济性判据：只有当收益项压过代价项时，EvoCut 才优于单层方案。工程上常见的错误是只算第一式——看到层数深就认为收益大，却忽略第二式在长输入下会翻转结论。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-50\">五十 · 与合并类、熵类的接口差异</h3>\n<p>EvoCut 与 ApET 的差异不只是判据，还有动作语义。ApET 的贪心合并会改变保留 token 的表示向量，后续层的注意力计算面对的是“混合后”的 key/value，因此合并必须在注意力计算之前完成，且合并顺序影响结果，天然带串行性；EvoCut 是硬删加 KV 重排，保留 token 的表示原封不动，重排只改位置索引，因此可以在预设层一次性完成，后续层仅对保留 token 计算。这一差异在批调度上很实际：合并类方案的串行贪心难以与连续批处理的新请求插入重叠，而 EvoCut 的一次性剪枝点是一个明确的同步屏障，屏障前后可以切分预填阶段，便于与分离式预填/解码的拓扑对齐。与 ERA 的差异则在判据的鲁棒性：熵判据对注意力分布的尖锐程度敏感，遇到 sink token 主导的层需要额外修正项，而 EvoCut 的累积天然把 sink 类 token 在多层的持续高注意力累加进去，不需要单独的修正机制——代价是它也无法区分“持续重要”与“某层偶然尖峰”，$\\gamma$ 衰减正是用来压制后者。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-51\">五十一 · 组合与降级路径</h3>\n<p>同族算法不必互斥。可行的组合是把视觉侧打分作为前置粗筛，把 EvoCut 作为精筛：粗筛在编码器输出处按视觉显著性去掉明显冗余的 token，把进入 LLM 的 $N_v$ 降下来，EvoCut 的多层统计缓存随之按比例缩小，缓解第二式里的代价项；精筛则在 LLM 内部按跨层演化决定最终保留集合。这条路径的代价是粗筛的误删不可恢复——被视觉侧判死的 token 不会进入多层统计，EvoCut 无从纠正。因此粗筛的保留率必须留足余量，粗筛比例越激进，组合方案越退化为纯视觉侧方案。降级路径则相反：当多层统计缓存撞上显存上限时，把 $L_p$ 从深层回退到浅层，或把 $\\gamma$ 调大以缩短有效累积窗口，用判据质量换缓存空间；再退一步则放弃累积，退化为固定层打分，此时 EvoCut 与单层方案在机制上同构，只是保留了 KV 重排的一次性优势。</p>\n<p>组合与降级都要在部署配方里显式声明，因为它们改变的是失败模式而非仅性能：粗筛组合把失败模式从“缓存挤占 KV”转成“粗筛误删不可恢复”；浅层降级把失败模式从“显存不足”转成“相同压缩率下精度回退”。诊断时若看到精度回退而显存宽裕，应先查剪枝层是否被降级过浅，而非怀疑累积公式本身。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-52\">五十二 · 选型的工程落点</h3>\n<p>最终判断落在一次预算核算上：先按输入形态估出 $N_v$ 与层数 $L$，用第二式算出多层统计缓存占 KV 预算的比例，若该比例使批大小必须下调超过一档，则 EvoCut 不成立，改选视觉侧打分或熵判据；若比例可接受，再用第一式估收益，确认剪枝点之后仍有足够层数摊薄一次性重排开销。这个顺序不能颠倒——先算代价再算收益，是因为代价项随输入规模线性增长而收益项随层数比例饱和，长输入场景下代价总是先撞墙。选型表给出的是首选，预算核算给出的是是否成立；两者冲突时以核算为准。对层数深、演化明显且输入规模可控的 VLM 预填，EvoCut 的一次性剪枝点还额外提供一个调度锚点：把该层作为预填阶段的分割线，前段做统计累积、后段做保留 token 计算，两段可分别与不同请求的批处理窗口对齐，这是同族其他算法给不出的拓扑自由度。</p>\n\n<h3 id=\"alg-evocut-multilayer-sec-53\">五十三 · 与同族剪枝方案的分界：选型判据与失效边界</h3>\n<p>把 EvoCut 放进视觉 token 压缩的同族谱系里，选型的第一刀不是看精度曲线，而是看“打分发生在哪一层、以什么信号为准”。ApET 以合并前后注意力近似误差为准则做贪心合并，本质是把冗余 token 融合而非丢弃，代价是合并算子本身引入额外的矩阵运算与位置重排；ERA 用熵与 sink 修正联合打分，信号更锐利但对 sink token 的识别依赖注意力分布的稳定性；VPRune 在 LLM 之前用视觉侧打分，完全绕开语言模型内部状态，延迟最低但对“进入 LLM 后才变重要”的 token 天然失明。EvoCut 的独特位置在于跟踪跨层演化轨迹并在预设层一次性剪枝——它既不像 VPRune 那样在门外决策，也不像 ApET 那样逐对合并，而是把决策点推迟到演化信息足够充分的那一层，用累积分数一次结算。因此当输入是长视频或高分辨率图像、且模型层数较深时，EvoCut 的信号优势才真正兑现；反之，若模型很浅、显著性在首层即基本定型，跨层统计的额外开销换不来精度，VPRune 或单层打分是更经济的解。</p>\n<p>决策可压成一张二维判据表：横轴是“显著性跨层演化强度”，纵轴是“可接受的统计缓存预算”。演化强且预算宽裕，选 EvoCut；演化强但预算紧张，退到 ERA 这类单层强信号方案并接受一定精度损失；演化弱且预算紧张，VPRune 直接前置剪枝；演化弱但要求极致精度、且能承受合并算力，ApET 的贪心合并更稳。演化分数本身决定了保留集合的规模敏感性：</p>\n<div class=\"formula\">$$s_i=\\sum_{l=l_0}^{l_1}\\gamma^{l-l_0}\\,a_i^{(l)},\\quad \\text{keep}=\\text{top-}k\\left(\\{s_i\\}\\right)$$</div>\n<p>其中衰减因子 γ 控制深层注意力对最终排序的贡献权重，γ 偏小则退化为近似单层打分、γ 接近 1 则深层噪声被等权放大。这个参数与剪枝层深度 L_p 共同构成 EvoCut 的两个调参自由度，也是它与 ERA、VPRune 最实质的接口差异——后两者的打分准则固定，不暴露“层间权重”这一维。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>打分信号</th><th>决策位置</th><th>主要系统代价</th><th>适用条件</th></tr></thead><tbody><tr><td>EvoCut</td><td>跨层累积显著性</td><td>预设层一次性剪枝</td><td>多层注意力统计缓存占显存与带宽</td><td>层数深、演化明显、缓存预算可容纳统计量</td></tr><tr><td>ApET</td><td>合并前后注意力近似误差</td><td>逐对贪心合并</td><td>合并算子算力与位置重排</td><td>要求高保真、可承受额外算力</td></tr><tr><td>ERA</td><td>熵与 sink 修正</td><td>单层联合打分</td><td>sink 识别依赖分布稳定</td><td>注意力分布稳定、需强信号</td></tr><tr><td>VPRune</td><td>视觉侧打分</td><td>LLM 之前</td><td>无 LLM 内部统计开销</td><td>显著性首层定型、追求低延迟</td></tr></tbody></table>\n<p>失效边界要盯住三处。其一是缓存规模：多层注意力统计随层数与 token 数线性增长，长视频或高分辨率输入下这部分占用会直接挤压 KV cache 预算，迫使批大小下调，吞吐随之塌陷——这是 EvoCut 在容量规划上最硬的天花板，规模上限由“统计缓存 + KV cache”共同约束，而非单看压缩率。其二是选层风险：浅层剪枝保留的算力节省最大，但此时演化信息尚不充分，误删后续才重要的 token 会在相同压缩率下造成精度回退；深层剪枝安全却收益递减，L_p 必须按模型深度逐档标定，不能跨模型复用。其三是重排同步：一次性剪枝后 KV 重排若与后续层注意力计算不同步，保留 token 的位置索引会错乱，解码一致性被破坏，这类错误不体现在精度均值上却会在长输出中累积放大。工程判断是：把 EvoCut 当作“用显存换精度”的方案来配置，先按缓存预算反推可承受的层数与 token 上限，再在该上限内选 L_p，而不是先定压缩率再补缓存。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 视觉Token压缩与合并</td></tr><tr><td>解决什么</td><td>视觉 token 在 LLM 不同层的显著性会动态演化，仅按首层或固定层打分剪枝会误删后续层才变重要的 token。</td></tr><tr><td>一句话机制</td><td>跟踪视觉 token 在多层中的注意力演化轨迹，按跨层累积显著性而非单层分数决定最终保留集合。</td></tr><tr><td>代价与失效</td><td>需缓存多层注意力统计，显存与带宽开销增加；剪枝层位置需按模型深度调参，浅层剪枝收益大但风险高</td></tr><tr><td>后继</td><td>视觉token预算感知批调度</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-evocut-multilayer · 共 8 个片段</p>\n";break;}}})();
